INSERT INTO `pertanyaan` (`id`, `topik_id`, `kode`, `kategori`, `pertanyaan`, `indeks_0`, `indeks_1`, `indeks_2`, `indeks_3`, `indeks_4`, `indeks_5`, `indeks_awal`, `panduan_indeks_5`, `keterangan_validasi_sumber`, `created_at`, `updated_at`) VALUES
(164, 1, 'ID 1.1', 'Mengidentifikasi Peran dan tanggung jawab Organisasi', 'Bagaimana pelaksanaan keamanan informasi di Organisasi, apakah:\r\n\r\n - Mendapat komitmen pimpinan tertinggi Organisasi yang juga terlibat dalam evaluasi berkala kondisi keamanan dan pencapaian sasarannya\r\n ⁠- Memiliki program keamanan (jangka pendek maupun menengah) termasuk penetapan kebijakan\r\n ⁠- Memiliki fungsi atau bagian yang secara spesifik mempunyai tugas, tanggungjawab, dan wewenang yang jelas untuk mengelola keamanan informasi dan menjaga kepatuhannya\r\n ⁠- Semua tanggungjawab dan kebutuhan keamanan informasi di Organisasi telah ditentukan dan dipetakan dengan lengkap kepada seluruh pihak yang ditetapkan sebagai tim resmi (tim SMKI) yang komposisinya diantaranya melibatkan Pengelola TIK, Bagian Umum, Keuangan, SDM, Bisnis, Audit Internal, dan sebagainya', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kebijakan keamanan informasi (Information Security Policy) yang ditandatangani pimpinan.\r\n2. Dokumentasi pembentukan Tim SMKI dengan anggota lintas fungsi (TIK, SDM, Keuangan, Bisnis, Audit, dll).\r\n3. Program kerja keamanan informasi jangka pendek, menengah, panjang (roadmap).\r\n4. Evaluasi berkala keamanan informasi (audit internal & eksternal, laporan tahunan).\r\n5. Notulensi rapat pimpinan terkait tinjauan keamanan informasi dan perbaikan strategi.\r\n6. Revisi kebijakan atau SOP berdasarkan hasil audit/evaluasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:58:31'),
(165, 1, 'ID 1.2', 'Mengidentifikasi Peran dan tanggung jawab Organisasi', 'Apakah Organisasi Anda sudah melakukan analisis keperluan sumber daya yang sesuai untuk mengelola dan menjamin kepatuhan program keamanan informasi dan pejabat/petugas pelaksana pengamanan informasi diberikan alokasi maupun kewenangan dalam pengelolaannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen analisis kebutuhan sumber daya (manusia, teknologi, anggaran) untuk keamanan informasi.\r\n2. Surat tugas/penetapan pejabat pengelola keamanan informasi yang memuat hak akses dan kewenangan.\r\n3. Anggaran khusus untuk keamanan informasi, termasuk pelatihan dan pengadaan alat keamanan.\r\n4. Evaluasi efektivitas alokasi sumber daya, misalnya laporan audit biaya & hasil.\r\n5. Pelatihan berkala untuk pelaksana keamanan informasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:58:37'),
(166, 1, 'ID 1.3', 'Mengidentifikasi Peran dan tanggung jawab Organisasi', 'Apakah telah ditetapkan dan dilakukan koordinasi secara terpola dan proaktif baik dengan pihak internal (SDM, Legal/Hukum, Umum, Keuangan dll) maupun dengan  pihak eksternal (regulator, aparat keamanan) dalam menerapkan dan menjamin kepatuhan pengamanan informasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Prosedur koordinasi keamanan informasi lintas unit (SDM, Legal, Keuangan, dll).\r\n2. Dokumentasi MoU atau kerja sama dengan pihak eksternal, seperti regulator atau aparat penegak hukum.\r\n3. Catatan atau notulensi rapat koordinasi rutin dengan pihak internal dan eksternal.\r\n4. Rencana kerja bersama atau forum rutin pengelolaan keamanan informasi.\r\n5. Evaluasi hasil koordinasi dan rekomendasi perbaikan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:08'),
(167, 1, 'ID 1.4', 'Mengidentifikasi Peran dan tanggung jawab Organisasi', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan proses untuk penanggungjawab pengelolaan keamanan informasi melaporkan kondisi kepatuhan program keamanan informasi pada pimpinan dan hasil pelaporan menjadi bagian dari proses pengambilan keputusan strategis di Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Template pelaporan keamanan informasi yang digunakan oleh penanggung jawab.\r\n2. Laporan berkala keamanan informasi (bulanan/kuartalan/tahunan) yang disampaikan ke pimpinan.\r\n3. Bukti tindak lanjut dari laporan, misalnya keputusan manajemen atas insiden atau kebijakan baru.\r\n4. Dokumen evaluasi efektivitas pelaporan, misalnya feedback pimpinan terhadap pelaporan.\r\n5. Integrasi laporan ke proses perencanaan strategis Organisasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:13'),
(168, 2, 'PR 4.53', 'Melindungi aplikasi', 'Apakah keseluruhan jaringan, sistem dan aplikasi sudah menggunakan mekanisme sinkronisasi waktu yang akurat, sesuai dengan standar yang ada?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Konfigurasi NTP server Organisasi.\r\n2. Bukti tangkapan layar telah sync NTP\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(169, 1, 'ID 1.5', 'Mengidentifikasi Peran dan tanggung jawab Organisasi', 'Apakah Organisasi telah menetapkan program untuk memenuhi sasaran kepatuhan pelindungan aset informasi dengan menetapkan persyaratan keamanan informasi secara terintegrasi pada seluruh proses bisnis, dan kriteria pencapaiannya sesuai dengan tanggungjawabnya?\r\n', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen program kerja perlindungan aset informasi, sesuai standar keamanan informasi.\r\n2. Dokumen integrasi keamanan informasi dalam proses bisnis (misalnya dokumen SOP tiap unit dengan komponen keamanan).\r\n3. Matriks tanggung jawab perlindungan aset informasi.\r\n4. Kriteria pencapaian dan indikator keberhasilan (KPI) terkait perlindungan aset informasi.\r\n5. Audit/evaluasi berkala dan hasilnya dijadikan dasar peningkatan kebijakan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:19'),
(170, 1, 'ID 1.6', 'Mengidentifikasi Peran dan tanggung jawab Organisasi', 'Apakah Organisasi sudah menunjuk fungsi/unit/Pejabat Pelindung Data Pribadi yang bertanggung-jawab dan berwenang dalam memantau penerapan kebijakan dan proses Pelindungan Data Pribadi dan memetakan pihak internal yang terkait PDP dalam pemrosesan data pribadi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Surat keputusan penunjukan PPDP dan struktur Organisasinya.\r\n2. Dokumen kebijakan dan prosedur pelindungan data pribadi (PDP) yang dijalankan oleh PPDP.\r\n3. Dokumentasi pemetaan proses dan pihak yang terlibat dalam pemrosesan data pribadi.\r\n4. Audit dan evaluasi berkala terhadap penerapan PDP.\r\n5. Rekomendasi dan tindak lanjut perbaikan dari hasil evaluasi tersebut.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:23'),
(171, 1, 'ID 1.7', 'Mengidentifikasi Peran dan tanggung jawab Organisasi', 'Apakah tanggungjawab untuk memutuskan, merancang, melaksanakan dan mengelola langkah kelangsungan layanan TIK (business continuity dan disaster recovery plans) sudah didefinisikan dan dialokasikan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen BCP (Business Continuity Plan) dan DRP (Disaster Recovery Plan) yang resmi dan terkini.\r\n2. Penetapan tanggung jawab BCP/DRP secara formal (struktur Organisasi, surat tugas).\r\n3. Catatan uji coba/simulasi BCP dan DRP, minimal tahunan.\r\n4. Evaluasi hasil simulasi dan tindakan korektif yang dilakukan.\r\n5. Revisi BCP/DRP berdasarkan hasil simulasi dan perubahan kondisi risiko.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:27'),
(172, 1, 'ID 2.8', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda telah mengidentifikasi legislasi, perangkat hukum dan standar lainnya terkait keamanan informasi yang harus dipatuhi dan menganalisa tingkat kepatuhannya serta menjadikan hasil analisis sebagai dasar untuk melakukan pembaharuan kebijakan/prosedur, rencana dan pelaksanaan program kerja?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Daftar regulasi yang harus dipatuhi (UU PDP, PP 71, ISO 27001, NIST, dll).\r\n2. Dokumen compliance matrix atau gap analysis kepatuhan hukum dan standar.\r\n3. Notulensi atau laporan evaluasi kepatuhan hukum secara berkala.\r\n4. Revisi kebijakan dan SOP sebagai hasil dari analisis regulasi.\r\n5. Bukti komunikasi dan sosialisasi hasil evaluasi kepada unit terkait.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(173, 1, 'ID 2.9', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda telah menetapkan dan menerapkan kerangka kerja pengelolaan perubahan terhadap sistem, proses bisnis dan proses teknologi informasi (termasuk perubahan konfigurasi) yang diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP pengelolaan perubahan yang melibatkan keamanan informasi.\r\n2. Formulir permintaan perubahan (RFC – Request for Change).\r\n3. Log perubahan konfigurasi dan sistem, termasuk approval.\r\n4. Laporan evaluasi dampak keamanan atas setiap perubahan besar.\r\n5. Catatan review dan peningkatan proses change management.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:32'),
(174, 1, 'ID 2.10', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda mempunyai strategi penerapan keamanan informasi termasuk penggunaan teknologi (penerapan dan pemutakhiran) yang disesuaikan dengan hasil analisa risiko dan direalisasikan menjadi program kerja Organisasi secara berkala (1-3-5 tahun)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen strategi keamanan informasi jangka 1-3-5 tahun.\r\n2. Laporan analisis risiko sebagai dasar penyusunan strategi.\r\n3. Roadmap program kerja keamanan informasi tahunan.\r\n4. Monitoring capaian strategi dan KPI keamanan informasi.\r\n5. Revisi strategi berdasarkan hasil evaluasi atau perubahan risiko', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(175, 1, 'ID 2.11', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda telah menetapkan dan melaksanakan program audit internal dan eksternal (independen) untuk mengevaluasi tingkat kepatuhan, konsistensi dan efektivitas penerapan keamanan informasi dengan cakupan keseluruhan aset informasi untuk disampaikan kepada pimpinan Organisasi sebagai upaya untuk meningkatkan langkah perbaikan penerapan keamanan informasi Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Jadwal audit internal dan eksternal yang rutin dan disetujui pimpinan.\r\n2. Laporan hasil audit lengkap, termasuk rekomendasi.\r\n3. Bukti tindak lanjut (Corrective Action Plan) atas temuan audit.\r\n4. Dokumen pelaporan hasil audit ke pimpinan.\r\n5. Evaluasi efektivitas hasil perbaikan dari audit sebelumnya.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:37'),
(176, 1, 'ID 2.12', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah kebijakan dan prosedur maupun dokumen lainnya yang diperlukan terkait keamanan informasi yang ditetapkan secara formal, telah dipublikasikan kepada semua staf/karyawan termasuk pihak terkait dan dengan mudah diakses oleh pihak yang membutuhkannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Portal/intranet yang memuat seluruh dokumen kebijakan/prosedur.\r\n2. Bukti sosialisasi melalui pelatihan, webinar, email blast.\r\n3. Log akses staf terhadap kebijakan/prosedur.\r\n4. Evaluasi pemahaman staf (quiz, kuesioner).\r\n5. Dokumen kebijakan yang mudah diakses dan berbahasa jelas.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:40'),
(177, 1, 'ID 2.13', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah keseluruhan kebijakan dan prosedur keamanan informasi yang ada merefleksikan kebutuhan mitigasi dari hasil kajian risiko keamanan informasi, maupun sasaran/obyektif tertentu yang ditetapkan oleh pimpinan Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Laporan kajian risiko (Risk Assessment Report).\r\n2. Matriks pengaitan antara kebijakan dan hasil kajian risiko.\r\n3. Dokumen sasaran keamanan informasi Organisasi.\r\n4. Revisi kebijakan berdasarkan perubahan risiko/sasaran.\r\n5. Evaluasi efektivitas kebijakan dalam mitigasi risiko.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:44'),
(178, 1, 'ID 2.14', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda sudah mendefinisikan dan mengkomunikasikan secara berkala konsekuensi/sanksi dari pelanggaran kebijakan keamanan informasi kemudian meninjau kepatuhan dan menegakkan kebijakan tersebut (menerapkan sanksi)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kebijakan disiplin dan sanksi terkait pelanggaran keamanan informasi.\r\n2. Bukti sosialisasi sanksi kepada karyawan.\r\n3. Catatan pelanggaran dan tindakan disiplin yang diambil.\r\n4. Statistik pelanggaran dan efektivitas penegakan aturan.\r\n5. Evaluasi dan revisi kebijakan disiplin berdasarkan tren pelanggaran.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 04:00:11'),
(179, 1, 'ID 2.15', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda menetapkan dan menerapkan proses untuk mengukur kepatuhan dan kontribusi pengguna terhadap Kebijakan Keamanan Informasi Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Form penilaian kinerja individu yang mencakup aspek keamanan informasi (SKP/IKU).\r\n2. Survei atau evaluasi kontribusi pengguna.\r\n3. Laporan pelaksanaan dan pencapaian kontribusi pengguna.\r\n4. Program penghargaan atau sanksi berdasarkan kontribusi.\r\n5. Review efektivitas keterlibatan pengguna dalam mendukung kebijakan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(180, 1, 'ID 2.16', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisai Anda sudah menerapkan proses untuk meninjau ulang secara berkala (minimal satu tahun sekali) seluruh kebijakan dan prosedur keamanan informasi untuk memastikan kelayakannya terkait dengan perubahan Organisasi, layanan, aspek operasional (geografis), dan infrastruktur termasuk pengelolaan perubahannya (misal kapan kebijakan/prosedur baru mulai diberlakukan), sebagai prasyarat untuk menerapkannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Jadwal formal review kebijakan/prosedur minimal tahunan.\r\n2. Daftar revisi kebijakan (revision history).\r\n3. Notulensi rapat tinjauan ulang kebijakan.\r\n4. Bukti sosialisasi kebijakan hasil revisi.\r\n5. Evaluasi efektivitas kebijakan hasil revisi terhadap perubahan Organisasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 04:00:14'),
(181, 1, 'ID 2.17', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah kebijakan dan prosedur keamanan informasi dikembangkan sesuai analisa sumber daya Organisasi, kepatuhan terhadap peraturan perundangan yang harus dipatuhi dan/atau menggunakan pendekatan kerangka kerja dan standar yang diakui (ISO 27001, PCI-DSS, HIPAA, NIST, CIS, SANS, dll)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 5, '1. Dokumen analisis kepatuhan regulasi dan standar (ISO, NIST, dll).\r\n2. Matriks kebijakan terhadap standar referensi.\r\n3. Rencana pengembangan kebijakan berdasarkan kebutuhan Organisasi.\r\n4. Evaluasi dan revisi kebijakan sesuai perubahan sumber daya.\r\n5. Bukti pelibatan manajemen dalam pengesahan kebijakan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(182, 1, 'ID 2.18', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah tersedia mekanisme untuk mengelola dokumen kebijakan dan prosedur keamanan informasi, termasuk penggunaan daftar induk, distribusi, penarikan dari peredaran dan penyimpanannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Daftar induk dokumen kebijakan/prosedur (master list).\r\n2. Prosedur distribusi, revisi, dan penarikan dokumen.\r\n3. Log distribusi dokumen kepada unit terkait.\r\n4. Bukti penghapusan dokumen lama dan penggantian resmi.\r\n5. Sistem DMS (Document Management System) aktif dan terkelola.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(183, 1, 'ID 2.19', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan kewajiban untuk memasukkan aspek keamanan informasi dalam fase perencanaan, pembangunan, dan pengembangan di semua proyek TI?\r\n', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP pengembangan proyek yang mencakup analisis keamanan.\r\n2. Template dokumen Security Requirement dalam proyek.\r\n3.  Laporan evaluasi keamanan di setiap fase proyek TI.\r\n4. Checklist keamanan sebelum implementasi proyek.\r\n5. Audit pasca implementasi proyek TI untuk menilai efektivitas pengamanan.', NULL, '2026-09-24 03:56:00', '2026-09-24 04:00:23'),
(184, 1, 'ID 2.20', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi anda menetapkan dan menerapkan kebijakan pembatasan penggunaan aset Organisasi untuk kepentingan pribadi, termasuk penggunaan jaringan dan fitur nirkabel (wireless access, NFC, Bluetooth dsb), layanan infrastruktur awan/cloud ?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan pembatasan penggunaan aset (PC, jaringan, cloud).\r\n2. SOP penggunaan fitur nirkabel, NFC, Bluetooth, dsb.\r\n3. Sistem pemantauan dan audit penggunaan aset.\r\n4. Tindakan korektif dan pelaporan penyalahgunaan.\r\n5. Evaluasi berkala dan peningkatan kebijakan pembatasan.', NULL, '2026-09-24 03:56:00', '2026-09-24 04:00:01'),
(185, 1, 'ID 2.21', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda menetapkan dan menerapkan kebijakan penggunaan perangkat milik pribadi yang digunakan untuk kepentingan Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kebijakan BYOD dan persyaratan teknis.\r\n2. Formulir persetujuan pengguna perangkat pribadi.\r\n3. Kebijakan enkripsi, MDM, dan pembatasan akses.\r\n4. Monitoring penggunaan dan insiden BYOD.\r\n5. Review dan perbaikan kebijakan BYOD berdasarkan insiden.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(186, 1, 'ID 2.22', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda telah menetapkan dan menerapkan kebijakan untuk selalu melakukan perbaikan (continual improvement) terhadap kinerja manajemen keamanan informasi sesuai dengan perkembangan risiko ataupun peraturamn perundangan yang ada.', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Program perbaikan berkelanjutan (continual improvement plan).\r\n2. Laporan hasil audit, risiko baru, dan umpan balik pengguna.\r\n3. Dokumen tindakan perbaikan dan peningkatan kebijakan.\r\n4. KPI peningkatan keamanan informasi.\r\n5. Review tahunan hasil perbaikan dan efektivitasnya.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(187, 1, 'ID 2.23', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda telah memiliki kebijakan Pelindungan Data Pribadi sesuai dengan Peraturan dan Perundangan yang berlaku dan memiliki program peningkatan pemahaman terhadap Pelindungan Data Pribadi yang terkait dengan pengelolaan aset informasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kebijakan PDP sesuai UU No. 27 Tahun 2022\r\n2. Peta pemrosesan data pribadi internal Organisasi.\r\n3. Program pelatihan/sosialisasi PDP ke seluruh staf.\r\n4. Evaluasi efektivitas edukasi PDP (quiz, survey).\r\n5. Laporan tindak lanjut insiden PDP (jika ada).', NULL, '2026-09-24 03:56:00', '2026-09-24 03:59:56'),
(188, 1, 'ID 2.24', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda anda telah menetapkan dan menerapkan metrik dan parameter (misal manual IKU) pengelolaan keamanan informasi untuk seluruh aset informasi maupun proses pengamanannya?\r\n', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh\r\n', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen metrik dan parameter (IKU, KPI, manual indikator).\r\n2. Laporan hasil pengukuran terhadap seluruh aset informasi.\r\n3. Evaluasi dan analisa kinerja berdasarkan parameter.\r\n4. Rencana perbaikan berbasis hasil pengukuran.\r\n5. Dashboard pengawasan kinerja keamanan informasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(189, 1, 'ID 2.25', 'Menyusun strategi, kebijakan, dan prosedur keamanan siber', 'Apakah Organisasi Anda anda sudah menerapkan target dan sasaran pengelolaan keamanan informasi (dapat berupa IKU atau SKP), termasuk bagi individu (pejabat dan petugas pelaksana) untuk berbagai area yang relevan, mengevaluasi pencapaiannya secara rutin, menerapkan langkah perbaikan untuk mencapai sasaran yang ada, termasuk pelaporan statusnya kepada pimpinan Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen penetapan target/sasaran keamanan informasi (Organisasi & individu).\r\n2. Formulir IKU/SKP petugas keamanan informasi.\r\n3. Laporan evaluasi berkala capaian sasaran.\r\n4. Dokumen perbaikan jika target belum tercapai.\r\n5. Bukti pelaporan kepada pimpinan dan review keputusan strategis.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(190, 1, 'ID 3.26', 'Mengelola aset informasi', 'Apakah Organisasi Anda menetapkan dan menerapkan proses inventarisasi aset yang berpotensi untuk menyimpan/memproses data (perangkat end-user, portabel dan mobile), perangkat jaringan, perangkat IoT, media penyimpan elektronik dan server)? (termasuk kepemilikannya)', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 5, '1. Daftar aset informasi yang komprehensif dan terkategori (hardware, mobile, IoT, storage, server).\r\n2. Dokumen prosedur inventarisasi dan pengelolaan aset.\r\n3. Identifikasi kepemilikan aset (asset ownership matrix).\r\n4. Sistem inventarisasi (misalnya CMDB atau aplikasi ITAM).\r\n5. Hasil audit internal tahunan terhadap data aset.\r\n6. Laporan pemutakhiran data aset secara periodik (misal triwulan).\r\n7. Review berkala terhadap validitas data aset dan tindak lanjutnya.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(191, 1, 'ID 3.27', 'Mengelola aset informasi', 'Apakah Organisasi Anda menetapkan dan menerapkan proses inventarisasi perangkat lunak berlisensi yang digunakan (diinstal) pada aset Organisasi, termasuk komponen perangkat lunak pihak ketiga (terkait dengan pekerjaan tertentu, contoh: penerapan manage service SIEM pihak ketiga) secara lengkap, akurat dan terpelihara?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Daftar perangkat lunak berlisensi per perangkat yang digunakan.\r\n2. Kebijakan dan SOP manajemen perangkat lunak (termasuk third-party).\r\n3. Bukti lisensi perangkat lunak (license keys, kontrak, SLA).\r\n4. Tool/software inventory scanner (seperti Lansweeper, SCCM, dsb).\r\n5. Review dan audit lisensi software tahunan.\r\n6. Dokumen persetujuan penggunaan software pihak ketiga.\r\n7. Catatan evaluasi risiko terkait penggunaan software dari pihak ketiga.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(192, 1, 'ID 3.28', 'Mengelola aset informasi', 'Apakah tersedia proses untuk melakukan pemutakhiran penerapan aset baru ke dalam lingkungan operasional, dan mendokumentasikannya, termasuk memutakhirkan dan meninjau ulang validitas daftar aset informasi secara berkala sesuai dengan kebijakan yang telah ditetapkan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP pemutakhiran daftar aset saat akuisisi, deployment, atau perubahan status.\r\n2. Formulir input/update aset dan bukti pelaksanaan.\r\n3. Log perubahan data aset (audit trail).\r\n4. Jadwal dan bukti review berkala daftar aset informasi.\r\n5. Bukti keterlibatan unit TIK dan unit pemilik aset dalam pemutakhiran.\r\n6. Daftar aset hasil validasi dan verifikasi.\r\n7. Laporan hasil perbaikan dari review sebelumnya.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(193, 1, 'ID 3.29', 'Mengelola aset informasi', 'Apakah Organisasi Anda memiliki metode / standar untuk menetapkan klasifikasi aset informasi dan TI? Dan apakah dilakukan tinjauan ulang reviu secara berkala?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh\r\n', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh\r\n', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan\r\n', 0, '1. Dokumen kebijakan/metodologi klasifikasi aset.\r\n2. Template klasifikasi aset berdasarkan parameter (nilai, sensitivitas, dampak, dsb.).\r\n3. Daftar aset yang sudah diklasifikasikan dengan label klasifikasi.\r\n4. SOP tinjauan ulang klasifikasi aset secara berkala.\r\n5. Laporan hasil review klasifikasi + revisi jika diperlukan.\r\n6. Sosialisasi klasifikasi ke pemilik aset dan user terkait.\r\n7. Catatan keputusan strategis terkait revisi klasifikasi (jika ada).', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(194, 1, 'ID 3.30', 'Mengelola aset informasi', 'Apakah Organisasi Anda melakukan klasifikasi informasi dan inventarisasi sesuai dengan kebijakan dan/atau peraturan perundangan yang berlaku (termasuk Data Pribadi) serta melakukan evaluasi tingkat kritikalitasnya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, 'Cukup memerlukan Dokumen:\r\n1. Dokumen Kebijakan Klasifikasi informasi dan Inventarisasi\r\n2. Contoh Dokumen Inventarisasi\r\n3. Contoh Dokumen Klasifikasi\r\n4. Dokumen Evaluasi Tingkat Kritikalitas Informasi\r\n\r\nKontrol meminta:\r\n1. organisasi melakukan klasifikasi informasi dan inventarisasi nya\r\n2. kebijakan klasifikasi informasi dan inventarisasi (apakah ada atau tidak)(termasuk data pribadi)\r\n3. melakukan evaluasi tingkat kritikalitas', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(195, 1, 'ID 3.31', 'Mengelola aset informasi', 'Apakah tersedia proses yang mengevaluasi dan mengklasifikasi aset informasi sesuai tingkat kritikalitas atau kepentingan aset bagi Organisasi (berdasarkan analisis risiko operasional, analisis bisnis, dan analisis strategis Organisasi), menetapkan penanggungjawab dan keperluan pengamanannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh\r\n', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, 'Kontrol meminta:\r\n1. proses evaluasi dan klasifikasi aset informasi sesuai dengan tingkat kritikalitas (berdasarkan analisis risiko, analisis bisnis dan analisis strategi organisasi)\r\n2. penetapan penanggungjawab\r\n3. keperluan pengamanannya\r\n\r\nCukup memerlukan Dokumen:\r\n1. dokumen hasil evaluasi dan klasifikasi aset informasi\r\n2. evaluasi dan klasifikasi berdasarkan analisis risiko, analisis bisnis dan analisis strategi organisasi\r\n3. dokumen yang menerangkat penanggungjawab aset informasi\r\n4. dokumen yang menjelaskan pengamanannya', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(196, 1, 'ID 3.32', 'Mengelola aset informasi', 'Apakah tersedia ketetapan terkait waktu penyimpanan (retensi) untuk klasifikasi data yang ada , dan syarat penghancuran penghapusan maupun pemusnahan data dan proses pelaksanaannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, 'ketetapan waktu penyimpanan retensi untuk klasifikasi data\r\nsyarat penghancuran, penghapusasn maupun pemusnahan data\r\nproses pelaksanaan\r\n\r\nCukup memerlukan Dokumen:\r\n1. Dokumen penetapan waktu penyimpanan (retensi) untuk Klasifikasi data yang ada\r\n2. Dokumen Kebijakan terkait penghancuran, penghapusan maupun pemusnahan data\r\n3. SOP Retensi Data', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(197, 1, 'ID 4.33', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda mempunyai program kerja pengelolaan risiko keamanan informasi yang terdokumentasi dan secara resmi digunakan, termasuk penanggung jawab dan pelaporannya sampai ke tingkat pimpinan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, 'program kerja pengelolaan risiko keamanan informasi secara resmi\r\npenanggungjawab pengelolaan risiko\r\npelaporan hasil pengelolaan risiko\r\n\r\nCukup memerlukan Dokumen:\r\n1. Dokumen Program Kerja pengelolaan risiko\r\n2. Dokumen yang menjelaskan penanggungjawab pengelola risiko\r\n3. Dokumen Laporan hasil pengelolaan risiko', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(198, 1, 'ID 4.34', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda mempunyai kerangka kerja pengelolaan risiko keamanan informasi yang terdokumentasi dan secara resmi digunakan, mencakup :\r\n\r\n - definisi dan hubungan tingkat klasifikasi aset informasi\r\n - tingkat ancaman\r\n - kemungkinan terjadinya ancaman \r\n - dampak kerugian\r\n - ambang batas tingkat risiko yang dapat diterima dan selera risiko', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan, terdokumentasi dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh\r\n\r\n', 'Kontrol sudah diterapkan, terdokumentasi dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh (semua cakupan sudah terisi secara lengkap)\r\n\r\n', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kerangka kerja manajemen risiko keamanan informasi.\r\n2. Tabel tingkat klasifikasi aset, ancaman, dan dampak kerugian.\r\n3. Penetapan risk appetite dan risk tolerance Organisasi.\r\n4. Metodologi penilaian risiko (probabilitas × dampak).\r\n5. Review berkala kerangka kerja dan validasi terhadap kebijakan terbaru.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(199, 1, 'ID 4.35', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda mengidentifikasi risiko dengan mengidentifikasi setidaknya :\r\n - aset utama/penting, proses kerja utama dan aset lain yang terkait keamanan\r\n - ancaman dan kelemahan yang terkait dengan aset\r\n - kepemilikan dan pihak pengelola (custodian) aset informasi yang ada', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Daftar aset utama dan proses bisnis terkait.\r\n2. Risk register (perhatikan kelengkapannya: ancaman, kerentanan, kepemilikan, pengella aset)\r\n3. Asset owner matrix (penanggung jawab dan custodian).\r\n4. SOP identifikasi aset dan kelemahan.\r\n5. Laporan validasi dan pembaruan identifikasi risiko secara berkala.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(200, 1, 'ID 4.36', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda melaksanakan penilaian risiko terhadap keamanan informasi secara berkala (menganalisa dampak, kemungkinan, level tingkat risiko sampai dengan penentuan langkah mitigasi (diterima, ditransfer, dihindari atau dimitigasi))?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh\r\n\r\n', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten, berkesinambungan dan selalu diupdate', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Jadwal dan dokumen risk assessment periodik.\r\n2. Risk assessment log: impact, likelihood, risk level, dan treatment.\r\n3. Rencana mitigasi risiko lengkap dengan statusnya.\r\n4. Validasi hasil risk assessment oleh pihak independen/internal auditor.\r\n5. Evaluasi efektivitas mitigasi dari hasil risk treatment plan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(201, 1, 'ID 4.37', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda anda sudah menyusun langkah mitigasi risiko disesuaikan dengan tingkat prioritas :\r\n\r\n - target penyelesaiannya dan penanggungjawabnya, \r\n - efektifitas penggunaan sumber daya yang dapat menurunkan tingkat risiko ke ambang batas yang bisa diterima\r\n - pemantauan berkala terhadap status penyelesaian langkah mitigasi risiko, untuk memastikan penyelesaian atau kemajuan kerjanya\r\n - evaluasi mitigasi risiko atau kontrol yang sudah diterapkan, melalui proses yang obyektif/terukur untuk memastikan konsistensi dan efektifitasnya\r\n - profil risiko berikut bentuk mitigasinya secara berkala dikaji ulang untuk memastikan akurasi dan validitasnya, termasuk merevisi profil terebut apabila ada perubahan kondisi yang signifikan atau keperluan penerapan bentuk pengamanan baru', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh (semua mitigasi lengkap terisi sesuai kriteria)', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan (hasil evaluasi diterapkan)', 0, '1. Risk treatment plan lengkap (target, penanggung jawab, dan prioritas).\r\n2. Laporan pemantauan status mitigasi (dashboard pelacakan).\r\n3. Evaluasi objektif efektivitas kontrol (via KPI, audit, atau simulasi).\r\n4. Revisi profil risiko berdasarkan perubahan situasi.\r\n5. Review berkala dan bukti perbaikan dari implementasi sebelumnya.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(202, 1, 'ID 4.38', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah kerangka kerja pengelolaan risiko secara berkala dikaji untuk memastikan kelaikan dan /meningkatkan efektifitasnya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Hasil kajian ditindaklanjuti dan terbukti meningkatkan efektifitas', 0, '1. Jadwal dan catatan review kerangka kerja risiko (minimal tahunan).\r\n2. Notulensi perubahan atau penyesuaian framework.\r\n3. Bukti keterlibatan manajemen dan unit strategis dalam review.\r\n4. Hasil evaluasi efektivitas kerangka kerja.\r\n5. Update versi kebijakan risiko berdasarkan hasil kajian.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00');
INSERT INTO `pertanyaan` (`id`, `topik_id`, `kode`, `kategori`, `pertanyaan`, `indeks_0`, `indeks_1`, `indeks_2`, `indeks_3`, `indeks_4`, `indeks_5`, `indeks_awal`, `panduan_indeks_5`, `keterangan_validasi_sumber`, `created_at`, `updated_at`) VALUES
(203, 1, 'ID 4.39', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah pengelolaan risiko menjadi bagian dari kriteria proses penilaian obyektif kinerja efektifitas pengamanan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh (dipetakan dengan IKU Keamanan)', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen IKU/SKP yang mencantumkan indikator efektivitas pengamanan berbasis risiko.\r\n2. Formulir penilaian kinerja dengan komponen risiko.\r\n3. Laporan kinerja unit berdasarkan indikator risiko.\r\n4. Evaluasi pencapaian berdasarkan penurunan tingkat risiko.\r\n5. Tindakan perbaikan berbasis hasil penilaian efektivitas.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(204, 1, 'ID 4.40', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi anda sudah menerapkan proses untuk mengevaluasi risiko termasuk rencana mitigasi risiko terhadap risiko baru yang muncul atau terjadinya ketidakpatuhan terhadap kebijakan yang ada karena penggunaan (atau penerapan) sistem baru?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP evaluasi risiko pada sistem/aplikasi baru.\r\n2. Dokumen hasil risk assessment pada sistem baru.\r\n3. Catatan penanganan risiko dari ketidakpatuhan.\r\n4. Rencana mitigasi risiko akibat perubahan sistem atau teknologi.\r\n5. Review dan update kebijakan akibat temuan risiko baru.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(205, 1, 'ID 4.41', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah tersedia daftar rekaman pelaksanaan keamanan informasi dan bentuk pengamanan yang sesuai dengan klasifikasinya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Master list pengamanan aset berdasarkan klasifikasi.\r\n2. Bukti penerapan kontrol pengamanan sesuai jenis aset (log akses, enkripsi, backup, dsb).\r\n3. Formulir validasi efektivitas pengamanan.\r\n4. Catatan evaluasi berkala terhadap kesesuaian kontrol dengan klasifikasi aset.\r\n5. Revisi kebijakan atau penguatan kontrol berdasarkan hasil evaluasi.\r\n6. Daftar rekaman pelaksanaan', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(206, 1, 'ID 4.42', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda telah menetapkan dan menerapkan program manajemen kerentanan siber dan mitigasinya, termasuk informasi adanya security patch baru, publikasi informasi kerentanan baru, proses vulnerability scanning dan/atau penetration testing secara berkala terhadap semua aset perangkat dan aplikasi (aplikasi web, aplikasi client-based, aplikasi mobile), wireless layanan daring yang diselenggarakan, sistem Organisasi pada layanan infrastruktur awan/cloud, server dan perangkat jaringan)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen program manajemen kerentanan (VM Program).\r\n2. Jadwal patching, scanning, dan pentest (berkala).\r\n3. Laporan hasil vulnerability scanning & penetration testing.\r\n4. Tindakan perbaikan dari hasil temuan (remediation tracker).\r\n5. Bukti evaluasi efektivitas program dan peningkatan sistemik.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(207, 1, 'ID 4.43', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda sudah menetapkan kebijakan dan prosedur pengamanan proses penetration testing, yang mencakup antara lain:\r\n\r\n- pengendalian dan pemantauan akun pengguna yang digunakan saat kegiatan\r\n- pengamanan dan pemantauan akses (white list IP) yang digunakan saat kegiatan\r\n- memastikan tidak ada ada Data Pribadi atau data sensitif lainnya yang terungkap atau tersalin saat kegiatan\r\n- memastikan pihak yang terlibat dalam kegiatan tidak melakukan aktivitas yang melanggar hukum atau dapat mengganggu operasional layanan', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP penetration testing (termasuk white list, user access, larangan pengambilan data pribadi).\r\n2. NDA & legal clearance vendor/pen-tester.\r\n3. Form persetujuan dan pengendalian aktivitas PT.\r\n4. Monitoring log selama kegiatan (IP, waktu akses, dsb).\r\n5. Evaluasi hasil PT dan tindak lanjut insiden (jika ada).', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(208, 1, 'ID 4.44', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan metode pemeringkatan pada kerentanan yang teridentifikasi berdasarkan pedoman / standar / acuan Organisasi yang disesuaikan dengan kerangka kerja risiko Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen metode risk-based vulnerability scoring (CVSS + organisasi).\r\n2. Mapping kerentanan ke level risiko.\r\n4. Dokumen Bukti pemeringkatan digunakan untuk action plan mitigasi.\r\n5. Dokumen Revisi metode klasifikasi sesuai perkembangan ancaman dan kerangka risiko.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(209, 1, 'ID 4.45', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan kebijakan maupun prosedur terkait untuk melakukan pemindaian kerentanan secara berkala, terotorisasi (authenticated scan) dan terotomasi, dengan memastikan cakupan seluruh aset informasi (infrastruktur dan aplikasi) dan frekuensi pelaksanaan yang disesuaikan dengan tingkat risiko.', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP vulnerability scanning (termasuk authenticated scan).\r\n2. Tool scanning aktif (Nessus, Qualys, dsb.) dan laporan hasil.\r\n3. Jadwal rutin pemindaian (disesuaikan tingkat risiko).\r\n4. Log otorisasi terhadap sesi scan.\r\n5. Evaluasi efektivitas scanning dan coverage terhadap semua aset.\r\n6. Dokumen SMKI', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(210, 1, 'ID 4.46', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan proses untuk melakukan validasi terhadap penilaian keamanan (VA atau Pentest), melakukan analisis root cause dari kerentanan keamanan yang ditemukan, dan melakukan perbaikan sesuai dengan prioritas atau kiritikalitas kerentanan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Template laporan validasi hasil VA/PT.\r\n2. Dokumen root cause analysis (RCA) dari setiap temuan kritikal.\r\n3. Catatan tindakan korektif (CAPA).\r\n4. Prosedur prioritisasi tindak lanjut berdasarkan kritikalitas.\r\n5. Evaluasi dan bukti keberhasilan mitigasi risiko dari RCA.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(211, 1, 'ID 4.47', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan proses untuk menganalisa dampak terkait terungkapnya data pribadi yang disimpan, diolah dan dipertukarkan secara ilegal atau karena insiden lain?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Template analisis dampak pelanggaran PDP (impact analysis).\r\n2. Laporan insiden data pribadi dan penanganannya.\r\n3. SOP penilaian dampak dan pelaporan ke otoritas (jika perlu).\r\n4. Evaluasi efektivitas penanganan insiden.\r\n5. Bukti peningkatan sistem atau kebijakan berdasarkan insiden.\r\n6. Dokumen SMKI', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(212, 1, 'ID 4.48', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi Anda sudah melakukan kajian risiko keamanan terkait Pelindungan Data Pribadi dan memastikan penerapan mekanisme pelindungan data pribadi sesuai dengan kebutuhan mitigasi risiko dan peraturan perundangan yang berlaku?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen Data Protection Impact Assessment (DPIA).\r\n2. Rencana mitigasi risiko PDP dan implementasinya.\r\n3. Penyesuaian sistem/proses sesuai hasil kajian.\r\n4. Audit kepatuhan terhadap regulasi PDP.\r\n5. Evaluasi ulang DPIA secara periodik.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(213, 1, 'ID 4.49', 'Menilai dan mengelola risiko Keamanan Siber', 'Apakah Organisasi anda sudah menetapkan dan menerapkan proses/metode untuk melakukan pemodelan ancaman (threat modelling) sesuai dengan attack surface (atau profil ancaman) dari infrastruktur atau aplikasi yang digunakan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP atau kerangka kerja threat modelling (misal: STRIDE, DREAD).\r\n2. Dokumen threat model sistem dan aplikasi.\r\n3. Peta attack surface (komponen, data flow, interface).\r\n4. Hasil identifikasi potensi eksploitasi dan risiko.\r\n5. Revisi sistem/arsitektur berdasarkan threat modelling dan evaluasinya.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(214, 1, 'ID 5.50', 'Mengelola risiko rantai pasok', 'Apakah aspek keamanan informasi yang mencakup pelaporan insiden, menjaga kerahasiaan, HAKI, tata tertib penggunaan dan pengamanan aset maupun layanan TIK tercantum dalam kontrak dengan pihak ketiga sesuai dengan konteks layanan atau kerja-sama yang ada?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Template kontrak standar yang mencantumkan klausul keamanan informasi (insiden, HAKI, akses, kerahasiaan, penggunaan aset).\r\n2. Checklist kepatuhan keamanan informasi sebelum penandatanganan kontrak.\r\n3. Review legal terhadap semua kontrak terkait TIK.\r\n4. Klausul tentang audit dan sanksi atas pelanggaran keamanan informasi.\r\n5. Evaluasi berkala terhadap kontrak aktif dan kepatuhan pihak ketiga.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(215, 1, 'ID 5.51', 'Mengelola risiko rantai pasok', 'Apakah tersedia prosedur penggunaan perangkat pengolah informasi milik pihak ketiga (termasuk perangkat milik pribadi dan mitra kerja/vendor) dengan memastikan aspek HAKI dan pengamanan akses yang digunakan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP penggunaan perangkat milik pribadi/vendor dalam lingkungan kerja.\r\n2. Ketentuan teknis kontrol akses, enkripsi, dan segmentasi jaringan untuk perangkat eksternal.\r\n3. Formulir persetujuan & deklarasi keamanan BYOD.\r\n4. Penerapan MDM (Mobile Device Management) atau endpoint protection.\r\n5. Audit dan pelaporan berkala terhadap penggunaan perangkat pihak ketiga.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(216, 1, 'ID 5.52', 'Mengelola risiko rantai pasok', 'Apakah tersedia mekanisme pengamanan dalam pengiriman aset informasi (perangkat dan dokumen) yang melibatkan pihak ketiga?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP pengiriman dokumen/perangkat (fisik/digital) ke pihak ketiga.\r\n2. Penggunaan metode pengamanan seperti enkripsi, tamper-proof packaging, logistik terpercaya.\r\n3. Bukti tracking log pengiriman aset.\r\n4. Checklist penerimaan & serah terima yang mencakup status keamanan.\r\n5. Evaluasi insiden terkait pengiriman dan peningkatan prosedur.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(217, 1, 'ID 5.53', 'Mengelola risiko rantai pasok', 'Apakah tersedia proses untuk mengamankan lokasi kerja dari keberadaan/kehadiran pihak ketiga yang bekerja untuk kepentingan Organisasi anda?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh\r\n', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh\r\n', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan\r\n', 0, '1. SOP pengelolaan akses fisik pihak ketiga (visitor log, ID, pengawasan).\r\n2. Pembatasan akses hanya ke area kerja relevan.\r\n3. Sistem pemantauan (CCTV, access control).\r\n4. Penandatanganan NDA sebelum memasuki ruang kerja terbatas.\r\n5. Evaluasi berkala terhadap akses fisik pihak eksternal dan audit keamanan fisik.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(218, 1, 'ID 5.54', 'Mengelola risiko rantai pasok', 'Apakah Organisasi Anda dalam pengembangan software oleh Organisasi, sudah menetapkan dan menerapkan persayaratan dalam melakukan kerjasama dengan pihak ketiga yang tepercaya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kontrak kerja sama dengan klausul keamanan SDLC (secure development).\r\n2. SOP penilaian keamanan partner pengembang software.\r\n3. Persyaratan sertifikasi atau standar pihak ketiga (ISO 27001, OWASP compliance).\r\n4. NDA dan perjanjian akses terbatas selama proses pengembangan.\r\n5. Evaluasi hasil pengembangan melalui security testing (VA/PT/source code review).', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(219, 1, 'ID 5.55', 'Mengelola risiko rantai pasok', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan proses untuk menginventarisasi penyedia layanan (daftar penyedia, klasifikasi, kontak) dan mengklasifikasikan penyedia layanan (berdasarkan karakteristik seperti : sensitivitas data, volume data, persyaratan ketersediaan, peraturan yang berlaku, risiko bawaan, dan risiko yang dimitigasi)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh\r\n', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh\r\n', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan\r\n', 0, '1. Master list penyedia layanan resmi (vendor register).\r\n2. Klasifikasi berdasarkan tingkat risiko (sensitivitas, volume data, SLA).\r\n3. Kontak resmi dan PIC dari tiap penyedia.\r\n4. Evaluasi berkala daftar & klasifikasi vendor.\r\n5. Penyesuaian klasifikasi sesuai perubahan regulasi atau kondisi layanan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(220, 1, 'ID 5.56', 'Mengelola risiko rantai pasok', 'Apakah Organisasi Anda sudah menetapkan dan melakukan proses penilaian terhadap penyedia layanan secara konsisten sesuai kebijakan manajemen penyedia layanan Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP penilaian vendor (pre-contract dan on-going).\r\n2. Template evaluasi penyedia: SLA, keamanan, kinerja, kepatuhan.\r\n3. Audit hasil kerja penyedia oleh internal/eksternal.\r\n4. Form evaluasi berkala & pembaruan kontrak berdasarkan hasil penilaian.\r\n5. Bukti pemutusan kontrak atau peningkatan kontrol akibat hasil penilaian.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(221, 1, 'ID 5.57', 'Mengelola risiko rantai pasok', 'Apakah tersedia proses untuk menonaktifkan penyedia layanan secara aman (contoh cakupan : penonaktifan akun penyedia, penghentian aliran data, penghapusan data Organisasi pada penyedia layanan secara aman dan lain-lain)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP offboarding vendor (penutupan akses, penghapusan data, pengembalian perangkat).\r\n2. Daftar periksa penghentian kerja sama/vendor decommissioning checklist.\r\n3. Bukti penonaktifan akun dan aliran data.\r\n4. Pernyataan tertulis pemusnahan data sensitif oleh vendor.\r\n5. Evaluasi proses offboarding untuk memastikan tidak ada celah keamanan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(222, 1, 'ID 5.58', 'Mengelola risiko rantai pasok', 'Apakah Organisasi Anda sudah menetapkan metode dan melakukan kajian risiko, menetapkan pembagian tanggung jawab keamanan, dan memastikan aspek hukum (jurisdiksi, hak dan kewenangan) terkait penggunaan layanan pihak ketiga?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kajian risiko pihak ketiga berdasarkan jenis layanan.\r\n2. Matriks tanggung jawab keamanan antara Organisasi dan pihak ketiga (RACI).\r\n3. Klausul kontrak terkait yurisdiksi hukum dan pelindungan hukum (termasuk GDPR/PDP).\r\n4. Checklist due diligence legal dan teknis.\r\n5. Evaluasi dan pembaruan pembagian tanggung jawab berkala.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(223, 1, 'ID 5.59', 'Mengelola risiko rantai pasok', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan proses evaluasi kelaikan keamanan layanan cloud yang digunakan secara resmi termasuk aspek ketersediaannya dan pemenuhan sertifikasi layanan berbasis ISO 27001?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP penilaian dan evaluasi keamanan layanan cloud.\r\n2. Bukti vendor cloud memiliki sertifikasi ISO 27001, SOC 2, atau lainnya.\r\n3. Evaluasi SLA layanan cloud (availability, integrity, confidentiality).\r\n4. Laporan keamanan dan audit layanan cloud.\r\n5. Review berkala terhadap penyedia cloud & tindakan korektif jika ditemukan celah', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(224, 2, 'PR 1.1', 'Mengelola identitas, autentikasi, dan kendali akses', 'Apakah definisi tingkatan akses yang berbeda untuk setiap klasifikasi aset informasi dan matriks yang merekam alokasi akses tersebut sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Dokumen kebijakan klasifikasi aset dan hak akses.\r\n2. Matriks kontrol akses (Access Control Matrix) yang memetakan pengguna, peran, sistem, dan hak aksesnya.\r\n3. SOP penetapan akses berdasarkan klasifikasi.\r\n4. log bukti implementasi.\r\n5. Evaluasi berkala terhadap akurasi matriks dan kepatuhan akses.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(225, 2, 'PR 1.2', 'Mengelola identitas, autentikasi, dan kendali akses', 'Apakah pengelolaan identitas elektronik yang mencakup proses otentikasi (username & password) sudah ditetapkan dan diterapkan secara konsisten (termasuk mengganti password default, kompleksitas password, umur password dan mekanisme reset password)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. SOP pengelolaan akun pengguna (termasuk pembuatan, perubahan, dan penghapusan akun).\r\n2. Konfigurasi teknis sistem otentikasi: password complexity, expiry, reset policy.\r\n3. Log audit aktivitas login pengguna.\r\n4. Kebijakan reset password\r\n5. Penilaian berkala terhadap efektivitas pengelolaan identitas.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(226, 2, 'PR 1.3', 'Mengelola identitas, autentikasi, dan kendali akses', 'Apakah kebijakan yang mengatur pelanggaran terhadap proses otentikasi tersebut sudah ditetapkan dan diberlakukan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen kebijakan pelanggaran autentikasi (misal: pemblokiran akun, pelaporan, sanksi internal).\r\n2. Mekanisme deteksi & pelaporan percobaan login tidak sah.\r\n3. Sistem monitoring insiden terkait otentikasi.\r\n4. Bukti implementasi pada sistem (lockout thresholds, alert).\r\n5. Rekap insiden pelanggaran & tindak lanjut berkala.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(227, 2, 'PR 1.4', 'Mengelola identitas, autentikasi, dan kendali akses', 'Apakah ada prosedur yang diterapkan untuk pengguna yang mutasi, keluar, atau tenaga kontrak/outsource yang habis masa kerjanya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. SOP offboarding dan exit clearance yang mencakup penarikan akses (akses fisik & digital).\r\n2. Form checklist pemutusan akses untuk semua jenis pegawai (tetap, kontrak, outsourcing).\r\n3. Log penonaktifan akun (misalnya log AD/LDAP/SIAM).\r\n4. Integrasi dengan sistem kepegawaian/HRIS.\r\n5. Review berkala efektivitas proses offboarding akses.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(228, 2, 'PR 1.5', 'Mengelola identitas, autentikasi, dan kendali akses', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan persyaratan dan prosedur yang jelas untuk pemberian akses, otentikasi, dan otorisasi dalam penggunaan aset informasi ?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Kebijakan formal pengelolaan akses.\r\n2. SOP permintaan akses baru dan approval berjenjang (berbasis peran).\r\n3. Template permohonan akses & bukti persetujuan.\r\n4. Penggunaan prinsip least privilege dan role-based access control (RBAC).\r\n5. Audit berkala terhadap pemberian akses & hak istimewa.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(229, 2, 'PR 1.6', 'Mengelola identitas, autentikasi, dan kendali akses', 'Apakah sistem dan aplikasi mendukung penggantian password secara otomatis, termasuk pengaturan untuk profil pengguna yang berbeda (misal admin dan pengguna biasa), pengaturan kompleksitas, penonaktifan password, dan larangan penggunaan kembali password lama untuk semua infrastruktúr dan aplikasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Konfigurasi sistem/aplikasi untuk:\r\n     - Password expiry\r\n     - Larangan reuse password\r\n     - Password complexity\r\n     - Otomatisasi reset password (tanpa intervensi admin)\r\n2. Profil pengguna berbeda (admin/user) & kebijakan khusus.\r\n3. Bukti penerapan sistem password policy (group policy AD, PAM tool, dsb).\r\n4. Audit keamanan password (hash, brute force test, dsb).\r\n5. Evaluasi dan penguatan berkala terhadap kebijakan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(230, 2, 'PR 1.7', 'Mengelola identitas, autentikasi, dan kendali akses', 'Apakah akses untuk pengelolaan sistem (administrasi) dilindungi dengan pengamanan yang berlapis, seperti penggunaan autentikasi multifaktor dan/atau kontrol ganda?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Kebijakan otentikasi multifaktor (MFA) untuk admin.\r\n2. Penggunaan PAM (Privileged Access Management) tools.\r\n3. Kontrol ganda (dual control) untuk tindakan kritikal.\r\n4. Segmentasi sistem admin dan audit log pemantauan aktivitas admin.\r\n5. Evaluasi berkala atas efektivitas pengamanan hak istimewa.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(231, 2, 'PR 1.8', 'Mengelola identitas, autentikasi, dan kendali akses', 'Apakah prosedur spesifik untuk menganalisis penggunaan akses (user access review) dan peninjauan hak akses, serta frekuensi pelaksanaannya sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. SOP peninjauan akses (frekuensi triwulan/tahunan).\r\n2. Bukti hasil access review & tindak lanjut perbaikan.\r\n3. Audit akses pengguna oleh pemilik data/sistem.\r\n4. Penggunaan sistem IAM/IGA (Identity Governance & Administration).\r\n5. Dokumentasi hasil evaluasi efektivitas proses review.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(232, 2, 'PR 1.9', 'Mengelola identitas, autentikasi, dan kendali akses', 'Apakah sistem dan aplikasi menerapkan pembatasan waktu akses, seperti otomatisasi proses timeouts, lockout setelah kegagalan login, dan penarikan akses?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Kebijakan dan konfigurasi sistem untuk:\r\n      - Session timeout\r\n      - Lockout setelah percobaan login gagal\r\n      - Auto log-off tidak aktif\r\n2. Setting default pada sistem/aplikasi.\r\n3. Pengujian teknis terhadap konfigurasi keamanan tersebut.\r\n4. Audit log terhadap penerapan.\r\n5. Evaluasi konfigurasi secara periodik.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(233, 2, 'PR 1.10', 'Mengelola identitas, autentikasi, dan kendali akses', ' Apakah Organisasi Anda menerapkan langkah-langkah keamanan khusus untuk melindungi infrastruktur jaringan dari akses yang tidak terotorisasi, baik segmen jaringan internal maupun akses dari luar? ', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Network Access Control (NAC) aktif dan dikonfigurasi.\r\n2. Firewall & IDS/IPS untuk segmentasi dan pemantauan akses.\r\n3. Kebijakan zero trust / VPN / segregasi jaringan internal-eksternal.\r\n4. Laporan audit jaringan dan uji penetrasi berkala.\r\n5. Dokumentasi evaluasi dan penguatan infrastruktur jaringan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(234, 2, 'PR 2.11', 'Melindungi aset fisik', 'Apakah tata tertib penggunaan perangkat komputer/laptop, smartphone, email, internet dan intranet sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen kebijakan dan tata tertib penggunaan perangkat komputer/laptop, email, internet, dan intranet.\r\n2. Panduan internal penggunaan perangkat kerja (BYOD, email kantor, Wi-Fi, remote work).\r\n3. Audit atau monitoring penggunaan layanan digital (misal: penggunaan email untuk non-kerja).\r\n4. Review berkala dan perbaikan aturan berdasarkan evaluasi kepatuhan & insiden.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(235, 2, 'PR 2.12', 'Melindungi aset fisik', 'Apakah pengamanan lokasi fisik/kerja sesuai dengan zonasi klasifikasi aset sudah ditetapkan dan diterapkan secara konsisten?\r\n \r\n (Zonasi = merah kuning hijau)\r\n (CCTV, kunci masuk, log book, security, dsb)', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Dokumen klasifikasi zona fisik lokasi kerja (layout area: hijau, kuning, merah).\r\n2. SOP dan bukti pemasangan kontrol fisik: CCTV, log book tamu, security check.\r\n3. Bukti pembatasan akses berdasarkan zona dan peran (visitor pass, ID badge).\r\n4. Evaluasi periodik keamanan fisik berdasarkan insiden atau hasil audit.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(236, 2, 'PR 2.13', 'Melindungi aset fisik', 'Apakah pengelolaan akses ke fasilitas fisik menggunakan kunci fisik dan elektronik sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. SOP manajemen akses fisik: kunci ruangan, kartu akses, biometrik.\r\n2. Bukti log sistem akses pintu otomatis (akses success/fail).\r\n3. Penggunaan sistem manajemen pengunjung & pemberian akses sementara.\r\n4. Evaluasi berkala terhadap hak akses fisik & ketidaksesuaian yang ditemukan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(237, 2, 'PR 2.14', 'Melindungi aset fisik', 'Apakah infrastruktur komputasi/ ruang server/ data center dibangun menggunakan material yang aman dari risiko kebakaran dan berada pada lokasi/ lingkungan yang aman?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Laporan asesmen lokasi & lingkungan ruang server (misalnya bebas banjir).\r\n2. Dokumen spesifikasi material bangunan (tahan api, anti lembab).\r\n3. Evaluasi risiko lingkungan sekitar (akses umum, pabrik, genset, dll).\r\n4. Simulasi evakuasi darurat dari ruang server/data center.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(238, 2, 'PR 2.15', 'Melindungi aset fisik', 'Apakah sistem pemadam api (termasuk smoke detector, alarm, APAR) yang sesuai dengan volume ruangan maupun tipe dan jumlah perangkat pada ruang infrastruktur komputasi/ ruang server/ data center tersedia, terpelihara dan diuji secara rutin?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Dokumentasi instalasi sistem smoke detector, alarm, dan APAR.\r\n2. Jadwal inspeksi dan pemeliharaan APAR (disertai log/checklist rutin).\r\n3. Sertifikat atau laporan pengujian sistem fire suppression (FM200, CO2).\r\n4. SOP tanggap darurat kebakaran dan bukti pelatihan simulasi.\r\n5. Laporan Simulasi', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(239, 2, 'PR 2.16', 'Melindungi aset fisik', 'Apakah sistem pengatur lingkungan (suhu dan kelembaban) sesuai dengan volume ruangan maupun tipe dan jumlah perangkat pada ruang infrastruktur komputasi/ ruang server/ data center tersedia, terpelihara dan diuji secara rutin?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Dokumentasi pemasangan AC presisi dan sistem kontrol kelembaban.\r\n2. Jadwal dan log pemeliharaan rutin sistem pendingin.\r\n3. Sistem monitoring suhu dan kelembaban otomatis (dashboard, alert).\r\n4. Laporan pengujian sistem HVAC (Heating, Ventilation & Air Conditioning).', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(240, 2, 'PR 2.17', 'Melindungi aset fisik', 'Apakah sistem pasokan daya listrik (generator, UPS, grounding, penangkal petir) sesuai dengan beban penggunaan daya operasional/darurat dengan redundansi yang sesuai dengan asesmen risiko pada infrastruktur komputasi/ ruang server/ data center tersedia, terpelihara dan diuji secara rutin?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Dokumen pemasangan sistem UPS, genset, grounding, dan penangkal petir.\r\n2. Jadwal dan laporan uji beban (load test) UPS/genset.\r\n3. SOP penggunaan daya darurat dan switchover otomatis.\r\n4. Evaluasi kesiapan sistem daya terhadap beban server real-time.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(241, 2, 'PR 2.18', 'Melindungi aset fisik', 'Apakah proses untuk memeriksa (inspeksi) dan merawat: perangkat komputer, fasilitas pendukungnya dan kelayakan keamanan lokasi kerja untuk menempatkan aset informasi penting ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. SOP inspeksi perangkat TI dan lokasi kerja untuk aset penting.\r\n2. Log hasil pemeriksaan perangkat kerja dan fasilitas penunjang (meja, jaringan, kursi ergonomis).\r\n3. Laporan audit lokasi penyimpanan perangkat penting.\r\n4. Bukti temuan dan tindakan koreksi (corrective action report).\r\n5.  Jadwal inspeksi & perawatan (bulanan/kuartalan).', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(242, 2, 'PR 2.19', 'Melindungi aset fisik', 'Apakah peraturan untuk mengamankan lokasi kerja penting (ruang server, ruang arsip) dari risiko perangkat atau bahan yang dapat membahayakan aset informasi (termasuk fasilitas pengolah informasi) yang ada di dalamnya ditetapkan dan diterapkan secara konsisten? (misal larangan penggunaan telpon genggam di dalam ruang server, menggunakan kamera dll)', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Kebijakan larangan membawa perangkat tertentu ke ruang sensitif (server, arsip).\r\n2. Papan pengumuman/peringatan di lokasi (ruang server).\r\n3. SOP pemeriksaan dan log aktivitas keluar masuk perangkat.\r\n4. Bukti pelatihan staf dan sosialisasi kebijakan larangan perangkat.\r\n5. Evaluasi insiden terkait pelanggaran perangkat & tindakan disipliner.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(243, 2, 'PR 3.20', 'Melindungi data', 'Apakah Organisasi anda menetapkan dan menerapkan kebijakan yang meliputi identifikasi dan pengamanan data (data disimpan, dikirim dan termasuk retensi data) Organisasi, serta pelindungan data pribadi pada perangkat kerja, termasuk apabila ada perangkat kerja milik pribadi yang digunakan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Kebijakan pengelolaan data (penyimpanan, pengiriman, retensi) termasuk BYOD.\r\n2. Dokumen pelindungan data pribadi (DPP) pada perangkat kerja.\r\n3. SOP penggunaan perangkat pribadi (termasuk enkripsi dan kontrol akses).\r\n4. Bukti pemantauan dan pelaporan kepatuhan kebijakan.\r\n5. Evaluasi berkala dan perbaikan dari insiden data yang disimpan/dikirim.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(244, 2, 'PR 3.21', 'Melindungi data', 'Apakah Organisasi anda sudah menetapkan dan menerapkan proses untuk memetakan alur pemrosesan data di internal dan pertukaran data dengan pihak eksternal, termasuk kapan, dimana data pribadi tersebut diperoleh serta pengamanannya di seluruh sistem dan jaringan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Data flow diagram (DFD) dan dokumen pemetaan alur data internal–eksternal.\r\n2. Identifikasi titik masuk dan penyimpanan data pribadi (form, API, email).\r\n3. Kontrol pengamanan di seluruh alur pemrosesan data (DLP, firewall, IDS).\r\n4. Audit trail pemrosesan data pribadi.\r\n5. Bukti review dan perbaikan pemetaan secara berkala.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00');
INSERT INTO `pertanyaan` (`id`, `topik_id`, `kode`, `kategori`, `pertanyaan`, `indeks_0`, `indeks_1`, `indeks_2`, `indeks_3`, `indeks_4`, `indeks_5`, `indeks_awal`, `panduan_indeks_5`, `keterangan_validasi_sumber`, `created_at`, `updated_at`) VALUES
(245, 2, 'PR 3.22', 'Melindungi data', 'Apakah Organisasi anda sudah menetapkan dan menerapkan proses terkait penyimpanan, pengolahan dan pertukaran data pribadi di Organisasi yang didokumentasikan, dimonitoring, dan dilaporkan secara berkala serta dilindungi dan dijaga agar tidak hilang, hancur, dipalsukan, diakses oleh pihak yang tidak sah sesuai dengan persyaratan perundang-undangan, peraturan, dan kontrak?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. SOP penyimpanan dan pengolahan data pribadi sesuai UU PDP.\r\n2. Kontrol keamanan sistem penyimpanan (access control, encryption, logging).\r\n3. Laporan monitoring akses dan pemrosesan data pribadi.\r\n4. Bukti audit dan pelaporan berkala ke manajemen.\r\n5. Evaluasi efektivitas kontrol dan perbaikannya', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(246, 2, 'PR 3.23', 'Melindungi data', 'Apakah Organisasi anda sudah menetapkan dan menerapkan proses penelusuran yang memastikan bahwa data stakeholder / klien / konsumen / pelanggan yang disimpan adalah data yang akurat?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Prosedur verifikasi keakuratan data stakeholder/klien/pelanggan.\r\n2. Bukti sistem penelusuran historis data (data lineage).\r\n3. Log koreksi dan pembaruan data.\r\n4. Monitoring berkala dan laporan validitas data.\r\n5. Evaluasi proses validasi data dan tindak lanjutnya.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(247, 2, 'PR 3.24', 'Melindungi data', 'Apakah Organisasi anda sudah menetapkan dan menerapkan proses untuk mengidentifikasi dan menetapkan basis hukum yang sesuai untuk menggunakan maupun mengambil data pribadi, termasuk penjelasan hak pemilik data, apa saja yang akan diberlakukan pada data pribadi tersebut dan menyimpan catatan persetujuan tersebut ?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP identifikasi dasar hukum (konsen, kontrak, kewajiban hukum, dll).\r\n2. Template dan bukti formulir persetujuan penggunaan data pribadi.\r\n3. Catatan audit persetujuan data dan hak-hak pemilik data.\r\n4. Pelatihan staf terkait legal basis pengumpulan data.\r\n5. Review hukum berkala atas dasar penggunaan data.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(248, 2, 'PR 3.25', 'Melindungi data', 'Apakah Organisasi Anda sudah menetapkan dan menerapkan proses untuk menyampaikan kebijakan pelindungan data pribadi  kepada stakeholder / klien / konsumen / pelanggan Anda sebelum setelah terjalin kerjasama?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kebijakan DPP yang diberikan sebelum/per awal kerja sama.\r\n2. Template komunikasi kepada stakeholder (email, form, website).\r\n3. Bukti penerimaan atau pengakuan oleh pihak eksternal.\r\n4. Mekanisme kontrol dan pelaporan kepatuhan penyampaian.\r\n5. Review isi dan efektivitas komunikasi kebijakan secara berkala.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(249, 2, 'PR 3.26', 'Melindungi data', 'Apakah Organisasi sudah menerapkan proses yang menjamin hak pemilik data pribadi untuk mengakses data tersebut serta memastikan data pribadi tersebut akurat dan dimutakhirkan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Prosedur permintaan akses oleh pemilik data.\r\n2. Portal layanan mandiri atau form permintaan data pribadi.\r\n3. Log pemrosesan permintaan hak akses/data update.\r\n4. Evaluasi kepatuhan terhadap SLA layanan akses data.\r\n5. Dokumentasi proses dan audit hak akses.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(250, 2, 'PR 3.27', 'Melindungi data', 'Apakah Organisasi anda sudah menetapkan dan menerapkan proses untuk memastikan saat memberikan data stakeholder / klien / konsumen / pelanggan kepada pihak ketiga, pihak stakeholder / klien / konsumen / pelanggan Anda memiliki kewenangan untuk mengetahui mengenai distribusi/pertukaran data milik mereka tersebut?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP distribusi data pribadi ke pihak ketiga.\r\n2. Dokumen perjanjian distribusi data (data sharing agreement).\r\n3. Notifikasi kepada pemilik data terkait distribusi data.\r\n4. Catatan audit distribusi dan respons pengguna.\r\n5. Evaluasi dan revisi kebijakan distribusi data.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(251, 2, 'PR 3.28', 'Melindungi data', 'Apakah Organisasi anda sudah menetapkan data apa saja yang akan disimpan/diolah/dipertukarkan, termasuk melalui layanan berbasis cloud?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen daftar jenis data yang diproses (termasuk cloud).\r\n2. Klasifikasi data dan pengelompokan berdasarkan sensitivitas.\r\n3. Matriks aset informasi & pemrosesan data.\r\n4. Monitoring proses pertukaran data.\r\n5. Review berkala atas daftar data yang diproses.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(252, 2, 'PR 3.29', 'Melindungi data', 'Apakah Organisasi anda sudah menetapkan kebijakan dan menerapkan langkah pengamanan data pribadi yang disimpan/diolah/dipertukarkan melalui layanan cloud?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan & SOP pelindungan data pribadi di cloud.\r\n2. SLA dan DPA dengan penyedia layanan cloud.\r\n3. Bukti enkripsi data pribadi saat transit dan disimpan di cloud.\r\n4. Audit kepatuhan cloud provider terhadap standar (misal ISO 27018).\r\n5. Evaluasi risiko dan penguatan keamanan cloud secara berkala.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(253, 2, 'PR 3.30', 'Melindungi data', 'Apakah Organisasi anda sudah menetapkan dan menerapkan proses untuk mengidentifikasi, menginventarisir, dan mengevaluasi kepatuhan terhadap syarat retensi data/aset informasi sesuai dengan peraturan perundangan yang ada dan menghapusnya jika sudah melewati batas retensi tersebut sesuai dengan klasifikasi informas?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kebijakan retensi data berdasarkan regulasi.\r\n2. SOP penghapusan data pasca-retensi (otomatis/manual).\r\n3. Daftar klasifikasi data dan jangka waktu retensinya.\r\n4. Catatan pemusnahan data sesuai klasifikasi.\r\n5. Evaluasi dan revisi kebijakan retensi secara berkala.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(254, 2, 'PR 3.31', 'Melindungi data', 'Apakah Organisasi sudah menerapkan proses terkait periode penyimpanan dan penghapusan/pemusnahan data pribadi sesuai dengan peraturan atau perjanjian dengan pemilik data maupun apabila sudah tidak ada keperluan yang sah untuk menyimpan/mengolahnya lebih lanjut atau atas permintaan pemilik data dan menyimpan catatan proses tersebut?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP penghapusan data pribadi atas permintaan pengguna.\r\n2. Formulir dan log permintaan penghapusan data.\r\n3. Bukti pelaksanaan dan pencatatan proses penghapusan.\r\n4. Template komunikasi ke pemilik data terkait penghapusan.\r\n5. Evaluasi efektivitas proses dan kepatuhan regulasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(255, 2, 'PR 3.32', 'Melindungi data', 'Apakah pembatasan terhadap keberadaan informasi yang dapat berguna bagi penyerang seperti network diagram, file konfigurasi, laporan uji penetrasi, email atau dokumen yang berisi kata sandi atau informasi lain yang penting untuk sistem operasi sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan klasifikasi informasi sensitif (konfigurasi, kata sandi, dll).\r\n2. Daftar dokumen sensitif & prosedur perlindungannya.\r\n3. Pembatasan akses berdasarkan jabatan/peran.\r\n4. Audit distribusi informasi sensitif.\r\n5. Review dan penghapusan konten sensitif berkala.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(256, 2, 'PR 3.33', 'Melindungi data', 'Apakah kontrol terhadap penggunaan kriptografi yang sesuai dengan semua perjanjian, undang-undang, dan peraturan yang berlaku sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan penggunaan algoritma kriptografi.\r\n2. Daftar regulasi/standar kripto yang dipatuhi (misal PP, ISO, NIST).\r\n3. Bukti sertifikasi software/hardware kripto.\r\n4. Log penggunaan dan audit algoritma enkripsi.\r\n5. Evaluasi dan audit efektivitas implementasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(257, 2, 'PR 3.34', 'Melindungi data', 'Apakah penerapan enkripsi untuk melindungi aset informasi penting sesuai kebijakan pengelolaan yang ada (in use, in transit and at rest) termasuk pengamanan dalam pengelolaan kunci enkripsi (termasuk sertifikat elektronik) berikut siklus penggunaannya sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP penerapan enkripsi end-to-end (in use, transit, at rest).\r\n2. Dokumen manajemen kunci dan sertifikat digital.\r\n3. Sistem rotasi kunci otomatis dan log enkripsi.\r\n4. Audit berkala terhadap penerapan enkripsi.\r\n5. Evaluasi performa & ketahanan terhadap ancaman.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(258, 2, 'PR 3.35', 'Melindungi data', 'Apakah telah diterapkan teknik pelindungan data (seperti mengaburkan data, data masking) agar hanya dapat dilihat oleh pihak yang mempunyai otoritas sesuai regulasi atau kebijakan? Mis: pengamanan data pribadi, data sensitif', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kebijakan penggunaan data masking/pseudonymization.\r\n2. Bukti penerapan masking di database/aplikasi.\r\n3. Catatan siapa yang dapat mengakses data asli.\r\n4. Audit efektivitas proteksi data tidak langsung.\r\n5. Revisi teknik berdasarkan insiden/kebutuhan baru.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(259, 2, 'PR 3.36', 'Melindungi data', 'Apakah telah diterapkan teknik proteksi integritas data (pada dokumen maupun dalam basis data) agar keutuhan dan keaslian data terjaga? (mekanisme hashing, signing, dll)', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan dan SOP pengamanan integritas data.\r\n2. Bukti implementasi hashing/signature di sistem dan dokumen.\r\n3. Monitoring log validasi keaslian data.\r\n4. Audit dan uji integritas berkala.\r\n5. Evaluasi dan perbaikan teknik integritas.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(260, 2, 'PR 3.37', 'Melindungi data', 'Apakah enkripsi pada semua perangkat mobile (laptop, handphone) karyawan dan semua media penyimpanan eksternal sesuai klasifikasi sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP enkripsi perangkat kerja mobile (laptop, HP) & storage eksternal.\r\n2. Bukti konfigurasi kebijakan enkripsi endpoint (MDM, BitLocker, dll).\r\n3. Log implementasi enkripsi dan pemantauan compliance.\r\n4. Audit akses perangkat terenkripsi.\r\n5. Evaluasi risiko & kepatuhan terhadap kebijakan enkripsi perangkat.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(261, 2, 'PR 3.38', 'Melindungi data', 'Apakah Organisasi menggunakan perangkat keras dan perangkat lunak original / produk asli dan memiliki sertifkat keamanan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, 'dapat merujuk Katalog Perangkat Teknologi Bersertifikat Keamanan, yaitu:\r\n1. Katalog Perangkat Teknologi Informasi Bersertifikat Keamanan Common Criteria (CC) Volume 2 (merujuk pada standar Common Criteria dan seri SNI\r\nISO/IEC 15408:2022);\r\n2. Katalog Modul Kriptografi Tersertifikasi Volume 1 (merujuk pada standar FIPS 140-3 dan SNI ISO/IEC 19790:2015);\r\n3. Katalog Produk Operation Technology (OT) Tersertifikasi ISASecure SSA Volume 1 (merujuk pada standar SNI IEC 62443-4-2 & SNI IEC 62443-3-3)', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(262, 2, 'PR 4.39', 'Melindungi aplikasi', 'Apakah Organisasi anda sudah menerapkan proses pengembangan sistem yang aman (Secure SDLC) dengan menggunakan prinsip atau metode sesuai standar platform teknologi yang digunakan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen kebijakan SDLC yang mengadopsi prinsip secure coding (misal: NIST, OWASP).\r\n2. Prosedur pengembangan aman yang diintegrasikan dalam tiap fase SDLC.\r\n3. Checklist keamanan dalam fase desain, implementasi, dan testing.\r\n4. Bukti pelaksanaan review berkala dan pelatihan SDLC untuk tim pengembang.\r\n5. Evaluasi efektivitas siklus SDLC dan hasil audit pengembangan.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(263, 2, 'PR 4.40', 'Melindungi aplikasi', 'Apakah ketetapan terkait prinsip pengembangan aplikasi yang aman (secure coding) yang digunakan untuk pengembangan aplikasi secara internal (in-house) maupun yang melibatkan pihak eksternal, termasuk proses source code review (baik secara manual atau menggunakan piranti lunak) sebelum dijalankan di lingkungan produksi, telah diterapkan dan ditinjau secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan secure coding berbasis OWASP/CERT.\r\n2. Prosedur source code review internal dan eksternal.\r\n3. Laporan hasil static code analysis (SAST).\r\n4. Log pelaksanaan secure code review dan mitigasinya.\r\n5. Audit berkala dan update standar secure coding.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(264, 2, 'PR 4.41', 'Melindungi aplikasi', 'Apakah Organisasi Anda melakukan pemisahan lingkungan pengembangan dengan lingkungan operasional dan mengelola akses kepada pengembang termasuk pengawasan dan tinjauannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Diagram dan kebijakan pemisahan lingkungan dev, test, prod.\r\n2. Kontrol akses pengguna terbatas di masing-masing environment.\r\n3. Log audit akses pengembang.\r\n4. SOP dan bukti review akses berkala.\r\n5. Evaluasi pelaksanaan pemisahan lingkungan dan perbaikannya.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(265, 2, 'PR 4.42', 'Melindungi aplikasi', 'Apakah keamanan dalam siklus operasional aset perangkat dan aplikasi sudah ditetapkan dan diterapkan secara konsisten (menonaktifkan aset yang tidak lagi diperlukan)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan dekomisioning aset TI.\r\n2. Daftar aset yang dinonaktifkan dan prosedur penghapusan aman.\r\n3. Log pemantauan status aset aktif dan non-aktif.\r\n4. Jadwal dan bukti review aset TI berkala.\r\n5. Evaluasi efektivitas kebijakan pengelolaan siklus aset.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(266, 2, 'PR 4.43', 'Melindungi aplikasi', 'Apakah kebijakan penggunaan aplikasi yang diunduh, diinstal, dan dioperasikan sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan instalasi aplikasi di endpoint.\r\n2. SOP pengajuan penggunaan software.\r\n3. Monitoring software yang terpasang dan digunakan.\r\n4. Log pelarangan atau penghapusan aplikasi tidak sah.\r\n5. Evaluasi penerapan dan pelanggaran terkait aplikasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(267, 2, 'PR 4.44', 'Melindungi aplikasi', 'Apakah kebijakan terkait whitelist aplikasi di Organisasi Anda yang memastikan bahwa hanya authorized software library (seperti: *.dll, *.so, *.ocx, *.exe, dsb) dan signed script (seperti: *.py, *.ps1, *.js, *.jar, dsb) yang dapat dijalankan oleh sistem telah ditetapkan dan ditinjau secara berkala?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Daftar whitelist software dan signed scripts.\r\n2. Kebijakan dan prosedur whitelist software.\r\n3. Bukti kontrol eksekusi aplikasi via endpoint protection (misal AppLocker).\r\n4. Log penambahan/penghapusan entri whitelist.\r\n5. Evaluasi berkala dan update daftar whitelist.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(268, 2, 'PR 4.45', 'Melindungi aplikasi', 'Apakah kebijakan terkait dengan pembatasan penggunaan scripting tools (seperti: Microsoft PowerShell dan Python) di Organisasi Anda sudah ditetapkan dan dilakukan peninjauan ulang berkala?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan pembatasan scripting (PowerShell, Python, dsb).\r\n2. Konfigurasi endpoint untuk pembatasan tools.\r\n3. Monitoring penggunaan scripting tools.\r\n4. Laporan pelanggaran dan tindakan perbaikan.\r\n5. Evaluasi ulang risiko penggunaan scripting tool secara berkala.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(269, 2, 'PR 4.46', 'Melindungi aplikasi', 'Apakah master image terkini dengan konfigurasi yang aman tersedia dan disimpan pada server yang dikonfigurasi secara aman?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Master image hardening standar (Windows/Linux).\r\n2. Lokasi penyimpanan image (server aman).\r\n3. Log pembuatan dan perubahan image.\r\n4. Dokumentasi uji coba image sebelum digunakan.\r\n5. Evaluasi kesesuaian image dengan kebutuhan terkini.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(270, 2, 'PR 4.47', 'Melindungi aplikasi', 'Apakah Organisasi anda sudah menerapkan kebijakan dan prosedur operasional untuk mengelola implementasi security patch, alokasi tanggung jawab untuk memonitor adanya rilis security patch baru, memastikan pemasangannya, mengelola pengecualiannya dan melaporkannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan manajemen patch (dengan SLA).\r\n2. Prosedur identifikasi, pengujian, dan deployment patch.\r\n3. Log instalasi dan pengecualian patch.\r\n4. Laporan kepatuhan patching mingguan/bulanan.\r\n5. Evaluasi dan audit efektivitas patch management.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(271, 2, 'PR 4.48', 'Melindungi aplikasi', 'Apakah kebijakan terkait aspek HAKI dalam penggunaan piranti lunak di aset TI sudah ditetapkan dan penerapannya sudah mencakup kondisi penggunaannya, pengamanannya secara konsisten termasuk tinjauan kepatuhannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan penggunaan software legal dan lisensi.\r\n2. Daftar perangkat lunak dan status lisensi.\r\n3. Log inspeksi kepatuhan lisensi.\r\n4. Bukti pelatihan penggunaan software legal.\r\n5. Evaluasi dan tindakan atas pelanggaran HAKI.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(272, 2, 'PR 4.49', 'Melindungi aplikasi', 'Apakah konfigurasi standar (port, protokol, service) untuk keamanan sistem bagi keseluruhan aset jaringan, sistem dan aplikasi, yang dimutakhirkan sesuai perkembangan (standar industri yang berlaku) dan kebutuhan sudah ditetapkan dan secara rutin dilakukan analisa kepatuhan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Template baseline konfigurasi sistem (port, protokol, layanan).\r\n2. SOP penerapan dan update konfigurasi standar.\r\n3. Hasil compliance check konfigurasi sistem.\r\n4. Log penyesuaian konfigurasi berdasarkan risiko baru.\r\n5. Evaluasi dan update baseline konfigurasi.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(273, 2, 'PR 4.50', 'Melindungi aplikasi', 'Apakah Organisasi telah menetapkan dan menerapkan proses pengelolaan konfigurasi perangkat komputasi (server, perangkat jaringan, sistem operasi dan aplikasi) yang diterapkan secara konsisten? ', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan pengelolaan konfigurasi.\r\n2. Prosedur perubahan dan pencatatan konfigurasi.\r\n3. Alat manajemen konfigurasi (misal Ansible, SCCM).\r\n4. Log perubahan konfigurasi.\r\n5. Audit efektivitas konfigurasi dan pelanggaran.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(274, 2, 'PR 4.51', 'Melindungi aplikasi', 'Apakah kebijakan yang mengatur pemisahan fungsi pada server yang berbeda (fisik maupun virtual) sesuai dengan risiko dan kritikalitasnya sudah ditetapkan dan diterapkan secara konsisten?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan pemisahan server berdasarkan fungsi.\r\n2. Diagram server dan peran masing-masing.\r\n3. Bukti penerapan server logis/fisik terpisah.\r\n4. Monitoring beban kerja dan segmentasi risiko.\r\n5. Evaluasi konsistensi pemisahan berdasarkan criticality.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(275, 2, 'PR 4.52', 'Melindungi aplikasi', 'Apakah keseluruhan infrastruktur jaringan, sistem dan aplikasi direncanakan dan dimonitor untuk memastikan ketersediaan kapasitas yang cukup untuk kebutuhan yang ada dan efektivitas keamanannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen perencanaan kapasitas (capacity planning).\r\n2. Monitoring performa sistem dan alert kelebihan beban.\r\n3. Evaluasi terhadap ketersediaan dan risiko overload.\r\n4. Laporan tren kapasitas dan proyeksi pertumbuhan.\r\n5. Revisi kapasitas berdasarkan hasil evaluasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(276, 2, 'PR 4.54', 'Melindungi aplikasi', 'Apakah setiap aplikasi yang ada memiliki spesifikasi dan fungsi keamanan yang diverifikasi/validasi pada saat proses pengembangan dan uji coba?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen spesifikasi keamanan aplikasi.\r\n2. Checklist validasi fungsi keamanan di test phase.\r\n3. Hasil uji coba kontrol akses, input validation, dsb.\r\n4. Log temuan keamanan selama test.\r\n5. Evaluasi ulang requirement keamanan aplikasi.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(277, 2, 'PR 4.55', 'Melindungi aplikasi', 'Dalam pengembangan software Organisasi Anda, apakah menggunakan algoritma enkripsi dan direviu secara berkala?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan pemilihan algoritma kriptografi.\r\n2. Daftar algoritma yang digunakan di sistem.\r\n3. Review berkala kekuatan algoritma (menghindari deprecated).\r\n4. Audit penggunaan algoritma sesuai standar.\r\n5. Evaluasi efektivitas enkripsi dalam pengembangan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(278, 2, 'PR 4.56', 'Melindungi aplikasi', 'Apakah Organisasi Anda menerapkan standar hardening configuration template pada aplikasi, database, dan sistem operasi, termasuk pengujiannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Log penerapan dan atau hasil uji hardening, termasuk:\r\n     - Checklist kesesuaian terhadap standar (CIS, STIG).\r\n     - hardening konfigurasi.\r\n2. Dokumen hasil evaluasi', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(279, 2, 'PR 4.57', 'Melindungi aplikasi', 'Dalam pengembangan software, apakah Organisasi Anda melakukan verifikasi bahwa versi semua software yang diperoleh dari luar Organisasi Anda masih didukung oleh pengembang atau dipertegas berdasarkan rekomendasi keamanan pengembang?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. SOP pengadaan software pihak ketiga.\r\n2. Bukti konfirmasi support vendor atau EOL status.\r\n3. Log versi dan kebijakan pembaruan.\r\n4. Review berkala kelayakan software pihak ketiga.\r\n5. Evaluasi rekomendasi keamanan terbaru vendor.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(280, 2, 'PR 4.58', 'Melindungi aplikasi', 'Dalam pengembangan dan penggunaan software, apakah Organisasi Anda sudah menetapkan dan menerapkan standar proteksi integritas terhadap perangkat lunak yang berjalan (termasuk kode sumber dan installer)', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan proteksi software (hashing, signing).\r\n2. Log hash/CRC dari installer atau kode sumber.\r\n3. Mekanisme verifikasi integritas saat eksekusi.\r\n4. Bukti pelaporan modifikasi tidak sah.\r\n5. Evaluasi keandalan mekanisme integritas.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(281, 2, 'PR 4.59', 'Melindungi aplikasi', 'Dalam pengembangan software secara mandiri, apakah Organisasi memastikan bahwa pengecekan kesalahan secara eksplisit dilakukan dan didokumentasikan untuk semua input, termasuk ukuran, tipe data, dan rentang atau format yang diterapkan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Laporan penerapan SDLC \r\n2. checlist pengujian software\r\n3. Dokumen laporan hasil evaluasi\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(282, 2, 'PR 4.60', 'Melindungi aplikasi', 'Apakah Organisasi anda sudah menerapkan teknik proteksi terhadap sistem email? \r\nSebagai contoh penerapan kebijakan Domain-based Message Authentication Reporting and Conformance (DMARC) atau protokol otentikasi email, metode sandbox, pengamanan komunikasi antar server email (TLS), enkripsi (PGP, S/MIME), dan lainnya', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan pengamanan email (SMTP, IMAP, antispam).\r\n2. Implementasi DMARC, DKIM, SPF.\r\n3. Sandbox uji attachment/malware email.\r\n4. Audit TLS & enkripsi komunikasi email.\r\n5. Evaluasi efektivitas perlindungan email.\r\n6. laporan Uji Komunikasi sama Tim CSIRT\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(283, 2, 'PR 4.61', 'Melindungi aplikasi', 'Apakah Organisasi anda menetapkan daftar aplikasi yang diperbolehkan untuk digunakan staf (pengguna biasa) dan dipantau penerapannya, termasuk memastikan pembaruan versi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Whitelist aplikasi pengguna biasa.\r\n2. Monitoring & notifikasi instalasi aplikasi non-otorisasi.\r\n3. Bukti update dan patch aplikasi yang digunakan.\r\n4. Log audit kepatuhan pengguna.\r\n5. Evaluasi aplikasi terhadap ancaman dan legalitas.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(284, 2, 'PR 4.62', 'Melindungi aplikasi', 'Apakah Organisasi Anda telah menggunakan Web Application Firewall (WAF) untuk melindungi seluruh aplikasi web Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Dokumen implementasi WAF (cloud/on-prem).\r\n2.Konfigurasi rule dan exception.\r\n3. Log blocking/prevention WAF.\r\n4. Analisa efisiensi WAF terhadap serangan (SQLi, XSS).\r\n5. Evaluasi berkala & tuning WAF rule.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(285, 2, 'PR 4.63', 'Melindungi aplikasi', 'Apakah Organisasi Anda telah menetapkan standar sistem operasi yang boleh digunakan untuk setiap perangkat desktop dan server yang kemudian dimutakhirkan dengan versi terkini?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Daftar OS yang diperbolehkan.\r\n2. SOP instalasi dan upgrade OS.\r\n3. Log pembaruan OS dan status patch.\r\n4. Kebijakan EOL (end-of-life) handling.\r\n5. Evaluasi standar OS berdasarkan risiko dan vendor.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(286, 2, 'PR 4.64', 'Melindungi aplikasi', 'Apakah Organisasi telah menetapkan dan menerapkan metode pencegahan perubahan yang tidak terotorisasi terhadap file system?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Kebijakan integritas file sistem.\r\n2. Tool integrity check (AIDE, Tripwire).\r\n3. Log pemantauan modifikasi file.\r\n4. Prosedur approval perubahan konfigurasi.\r\n5. Evaluasi efektivitas dan pelaporan pelanggaran.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(287, 2, 'PR 4.65', 'Melindungi aplikasi', 'Apakah Organisasi Anda memastikan penggunaan add-on dan plugin web browser dan email client sudah sesuai dengan ketentuan Organisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Daftar add-on & plugin yang diperbolehkan.\r\n2. SOP persetujuan plugin sebelum instalasi.\r\n3. Monitoring penggunaan plugin pengguna.\r\n4. Log pelanggaran dan tindakan koreksi.\r\n5. Evaluasi keamanan plugin secara periodik.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(288, 3, 'DE 1.1', 'Mengelola deteksi Peristiwa Siber', 'Apakah Organisasi telah membentuk fungsi atau unit kerja yang bertugas memantau ketersediaan/aktivitas/kinerja sistem dan mendeteksi adanya peristiwa siber (baik internal maupun eksternal) sesuai dengan lingkup operasional yang ada, termasuk adanya keterlibatan pihak ketiga?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. SK pembentukan SOC atau fungsi pemantauan siber\r\n2. Struktur Organisasi dan penempatan personel SOC\r\n3. Jadwal operasional 24/7 (shift roster) (opsional)\r\n4. SOP dan MoU kerja sama dengan MSSP (opsional)\r\n5. dokuman evaluasi proses bisnis', 'Tidak ada pihak ketiga', '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(289, 3, 'DE 1.2', 'Mengelola deteksi Peristiwa Siber', 'Apakah Organisasi telah menetapkan dan menerapkan kerangka kerja pemantauan aktivitas/kinerja sistem dan deteksi peristiwa siber (termasuk klasifikasi insiden dan triase/ pemilahan insiden) sesuai dengan keseluruhan lingkup operasional dan attack surface yang ada, termasuk adanya keterlibatan pihak ketiga?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen kerangka kerja pemantauan dan deteksi insiden\r\n2. Panduan klasifikasi dan prioritisasi insiden\r\n3. SOP triase dan penanganan insiden\r\n4. Laporan review insiden dan evaluasi efektivitas deteksi', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00');
INSERT INTO `pertanyaan` (`id`, `topik_id`, `kode`, `kategori`, `pertanyaan`, `indeks_0`, `indeks_1`, `indeks_2`, `indeks_3`, `indeks_4`, `indeks_5`, `indeks_awal`, `panduan_indeks_5`, `keterangan_validasi_sumber`, `created_at`, `updated_at`) VALUES
(290, 3, 'DE 1.3', 'Mengelola deteksi Peristiwa Siber', 'Apakah Organisasi memiliki SDM dengan jumlah dan kompetensi yang memadai untuk memantau ketersediaan/aktivitas/kinerja sistem, mendeteksi peristiwa siber dan mengawaki perangkat deteksi?', 'Belum memiliki SDM baik secara jumlah dan kompetensi yang memadai ', 'Jumlah SDM dan kompetensi kurang memadai ', 'Jumlah SDM sudah memadai namun kompetensi kurang memadai [tidak merata]', 'Jumlah SDM dan Kompetensi sudah memadai, namun belum mencakup keseluruhan lingkup operasional', 'Jumlah SDM dan Kompetensi memadai untuk seluruh lingkup operasional', 'Dilakukan evaluasi kinerja dan perbaikan secara rutin', 3, '1. Struktur Organisasi SOC/Tim Keamanan TI\r\n2. Daftar Personel & Job Description\r\n3. Sertifikat Kompetensi (CEH, Security+, CHFI, dll)\r\n4. Rencana & Realisasi Pelatihan Berkala\r\n5. Hasil Evaluasi Kinerja\r\n6. Dokumen Analisis Beban Kerja', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(291, 3, 'DE 1.4', 'Mengelola deteksi Peristiwa Siber', 'Apakah Organisasi telah menerapkan kemampuan deteksi yang sudah dikonfigurasi untuk menerima data log yang diperlukan dari semua sistem sesuai lingkup operasional yang ada? (jaringan, sistem, aplikasi, endpoint, perangkat keamanan)', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Diagram integrasi log dengan SIEM\r\n2. Daftar sumber log aktif (server, endpoint, firewall, dsb)\r\n3. Contoh hasil korelasi dan notifikasi otomatis\r\n4. Retensi log sesuai kebijakan (minimal 6 bulan – 1 tahun)\r\n5. SOP pengelolaan log', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(292, 3, 'DE 2.5', 'Menganalisis anomali dan Peristiwa Siber', 'Apakah dalam menerapkan kerangka kerja pemantauan dan deteksi Organisasi anda sudah menentukan referensi dasar (baseline) operasional seluruh sistem, menyusun dan menggunakan use case berbagai skenario untuk dapat menemukenali anomali atau serangan yang terjadi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Dokumen baseline performa dan aktivitas sistem\r\n2. Use-case deteksi insiden (DoS, brute force, privilege abuse, dll)\r\n3. Hasil uji skenario use-case pada sistem\r\n4. Catatan perubahan baseline dan penyesuaiannya', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(293, 3, 'DE 2.6', 'Menganalisis anomali dan Peristiwa Siber', 'Apakah Organisasi anda menerapkan kemampuan untuk menerima, menganalisis, dan memverifikasi informasi perubahan data, aplikasi, dan konfigurasi?', 'Belum ada penerapan kontrol', 'Sudah menerapkan kemampuan menerima sebagian informasi perubahan data, aplikasi, dan konfigurasi', 'Sudah menerapkan kemampuan menerima informasi perubahan data, aplikasi, dan konfigurasi', 'Sudah menerapkan kemampuan menerima dan menganalisis informasi perubahan data, aplikasi, dan konfigurasi, namun belum konsisten', 'Sudah menerapkan kemampuan menerima, menganalisis dan memverifikasi informasi perubahan data, aplikasi, dan konfigurasi secara menyeluruh', 'Sudah menerapkan kemampuan menerima, menganalisis dan memverifikasi informasi perubahan data, aplikasi, dan konfigurasi secara menyeluruh dan telah mengotomatisasi laporan analisisnya [data, aplikasi, konfigurasi]', 3, '1. Sistem Monitoring & Logging Konfigurasi\r\n2. Audit Trail Otomatis & Terintegrasi\r\n3. SOP Manajemen Perubahan (Change Management)\r\n4. Integrasi ke SIEM atau Platform Otomasi Lain\r\n5. Contoh Laporan Otomatis Perubahan Konfigurasi/Aplikasi/Data', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(294, 3, 'DE 2.7', 'Menganalisis anomali dan Peristiwa Siber', 'Apakah Organisasi sudah menerapkan kemampuan untuk mendeteksi aktivitas dan perubahan konfigurasi akun setiap profil pengguna yang mencakup pemantauan, analisis dan pelaporan secara berkala?', 'Belum ada penerapan kontrol', 'Sudah menerapkan kemampuan untuk mendeteksi aktivitas dan perubahan konfigurasi sebagian akun internal setiap profil pengguna yang mencakup pemantauan, analisis dan pelaporan secara berkala', 'Sudah menerapkan kemampuan untuk mendeteksi aktivitas dan perubahan konfigurasi semua akun internal setiap profil pengguna yang mencakup pemantauan, analisis dan pelaporan secara berkala', 'Sudah menerapkan kemampuan untuk mendeteksi aktivitas dan perubahan konfigurasi semua akun internal dan eksternal setiap profil pengguna yang mencakup pemantauan, analisis dan pelaporan secara berkala', 'Sudah menerapkan kemampuan untuk mendeteksi aktivitas dan perubahan konfigurasi semua akun internal dan eksternal setiap profil pengguna yang mencakup pemantauan, analisis dan pelaporan secara berkala, serta dilakukan proses evaluasi hasil deteksi secara berkala', 'Sudah menerapkan kemampuan untuk mendeteksi aktivitas dan perubahan konfigurasi semua akun internal dan eksternal setiap profil pengguna yang mencakup pemantauan, analisis dan pelaporan secara berkala, serta dilakukan proses evaluasi hasil deteksi secara berkala. Kegiatan ini (proses) telah terotomatisasi dari level pemantauan, analisis dan pelaporan.', 2, '1. Implementasi UEBA (User & Entity Behavior Analytics)\r\n2. Log Aktivitas Pengguna\r\n3. SOP Monitoring & Reporting Aktivitas Akun\r\n4. Dashboard Real-Time Aktivitas Akun\r\n5. Otomatisasi Proses\r\n6. Laporan Evaluasi Berkala', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(295, 3, 'DE 2.8', 'Menganalisis anomali dan Peristiwa Siber', 'Apakah Organisasi anda menetapkan dan menerapkan skema proteksi data untuk mendeteksi perubahan dan mencegah keluarnya data berklasifikasi tanpa otorisasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1.Kebijakan klasifikasi data dan proteksi\r\n2. Implementasi DLP tools (endpoint dan jaringan)\r\n3. Laporan pencegahan insiden data leakage\r\n4. SOP respon terhadap pelanggaran kebocoran data', 'menggunakan enskripsi dan proteksi becrypt(utama), md25, sha256, base64 ', '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(296, 3, 'DE 2.9', 'Menganalisis anomali dan Peristiwa Siber', 'Apakah Organisasi anda menerapkan kemampuan untuk mendeteksi adanya perubahan/penambahan endpoint dan/atau perangkat jaringan (switch, WLAN)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah menerapkan kemampuan untuk mendeteksi adanya perubahan/penambahan endpoint dan/atau perangkat jaringan', 'Sudah menerapkan kemampuan untuk mendeteksi adanya perubahan/penambahan endpoint dan/atau perangkat jaringan', 'Sudah menerapkan kemampuan untuk mendeteksi adanya perubahan/penambahan endpoint dan/atau perangkat jaringan dan dilakukan proses evaluasi hasil deteksi secara berkala', 'Sudah menerapkan kemampuan untuk mendeteksi adanya perubahan/penambahan endpoint dan/atau perangkat jaringan, dilakukan proses evaluasi hasil deteksi secara berkala dan prosesnya telah terotomatisasi', 3, '1. Implementasi Network Access Control (NAC) atau solusi asset discovery\r\n2. Sistem Inventarisasi Otomatis Endpoint\r\n3. Alert Otomatis Penambahan Perangkat (SIEM, NAC, dll)\r\n4. Dashboard Deteksi Endpoint & Perangkat Baru\r\n5. Laporan Evaluasi Deteksi\r\n6. SOP Penanganan Endpoint Baru & Unauthorized Devices', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(297, 3, 'DE 3.10', 'Memantau Peristiwa Siber berkelanjutan', 'Apakah Organisasi anda telah menerapkan kerangka kerja deteksi dini dengan menggunakan informasi analisis ancaman (Cyber Threat Intelligence) yang telah diintegrasikan dan dikorelasikan dengan hasil pemantauan/deteksi peristiwa siber?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Subscription intelijen ancaman (CTI feed, ISAC, dsb)\r\n2. Integrasi CTI dengan SIEM atau platform analitik\r\n3. Contoh penggunaan CTI dalam mendeteksi insiden\r\n4. SOP penggunaan dan pembaruan threat intelligence', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(298, 3, 'DE 3.11', 'Memantau Peristiwa Siber berkelanjutan', 'Apakah Organisasi merencanakan dan menerapkan program pro aktif untuk menemukenali potensi kelemahan pada sistem? (bug bounty, threat hunting)', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Program atau roadmap threat hunting\r\n2. Laporan aktivitas threat hunting\r\n3. Program bug bounty dan hasil pelaporan\r\n4.SOP tindak lanjut temuan bug', 'tidak ada anggaran', '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(299, 3, 'DE 3.12', 'Memantau Peristiwa Siber berkelanjutan', 'Apakah Organisasi anda menetapkan dan menerapkan proses untuk menganalisis hasil pemantauan dan deteksi, melaporkannya secara berkala dan formal kemudian menyusunnya untuk menjadi pembelajaran (lesson learned)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Template dan laporan rutin monitoring/deteksi\r\n2. Notulen rapat evaluasi hasil monitoring\r\n3. Dokumen lesson learned dan tindak lanjutnya\r\n4. Bukti perbaikan berdasarkan hasil pemantauan\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(300, 4, 'GU 1.1', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda menetapkan dan menerapkan kebijakan dan prosedur pengelolaan insiden siber?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Dokumen kebijakan dan prosedur pengelolaan insiden siber yang telah ditetapkan secara formal.\r\n2. Evaluasi tahunan efektivitas kebijakan/prosedur melalui audit internal dan/atau eksternal.\r\n3. Bukti perbaikan prosedur berdasarkan hasil evaluasi insiden sebelumnya (continuous improvement).\r\n4. Log bukti implementasi insiden nyata (termasuk post-incident review)', 'Sudah ada rancangan tapi belum lengkap', '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(301, 4, 'GU 1.2', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda sudah membentuk tim yang bertanggungjawab untuk mengelola insiden siber yang mewakili berbagai pemangku kepentingan (penanggung jawab layanan dan/atau pemilik aset)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Surat keputusan pembentukan tim insiden siber lintas fungsi (TI, hukum, komunikasi, layanan)/CSIRT/TTIS\r\n2. Struktur Organisasi lengkap dengan job description.\r\n3. Evaluasi berkala terhadap kesiapan dan kapabilitas tim (misal melalui simulasi insiden/cyber drill).\r\n4. Laporan aktivitas tim dan tindak lanjut atas perbaikan/respons insiden.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(302, 4, 'GU 1.3', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda sudah membentuk tim manajemen krisis yang merepresentasikan pimpinan puncak yang memiliki wewenang dan bertanggungjawab menetapkan status bencana, memantau pelaksanaan keberlangsungan layanan (BCP) dan pemulihan bencana (DRP) sampai dengan status dinyatakan kembali normal?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. SK penetapan Crisis Management Team oleh pimpinan puncak Organisasi.\r\n2. Prosedur aktivasi status bencana dan transisi ke normal.\r\n3. Laporan hasil evaluasi efektivitas respon terhadap simulasi dan/atau insiden aktual.\r\n4. Bukti perbaikan dan penyempurnaan prosedur pasca insiden/simulasi.\r\n5. Dokumen BCP dan DRP', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(303, 4, 'GU 1.4', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah tim respon insiden siber di Organisasi Anda telah memiliki kompetensi dalam mengidentifikasi, melaporkan, merespons, mengatasi, dan memulihkan sistem dari Insiden Siber untuk meminimalkan dampak yang diakibatkan sesuai standar yang berlaku?\r\n', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Sertifikasi anggota tim (misal: CSIRT, CEH, CHFI, SANS GCIH).\r\n2. Log pelatihan rutin dan simulasi insiden.\r\n3. Laporan evaluasi efektivitas tim dalam insiden nyata/simulasi.\r\n4. Bukti peningkatan kompetensi berdasarkan hasil evaluasi dan kebutuhan strategis.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(304, 4, 'GU 1.5', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah pimpinan di Organisasi anda telah menetapkan program dan mengalokasikan sumber daya (SDM, anggaran, dan dukungan teknologi) untuk kesiapan pengelolaan insiden?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Dokumen alokasi anggaran khusus untuk penanganan insiden.\r\n2. Penetapan sumber daya manusia dan teknologi dalam RKAT dan RBA Organisasi.\r\n3. Evaluasi tahunan terhadap kecukupan sumber daya dan revisi perencanaan bila perlu.\r\n4. Notulen rapat atau rekomendasi perbaikan dari evaluasi kesiapan.', 'hanya anggaran tidak ada', '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(305, 4, 'GU 1.6', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi Anda telah menerapkan program peningkatan kepedulian dan pelatihan untuk karyawan tentang cara mengidentifikasi, penanganan, dan pelaporan suatu insiden keamanan informasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Jadwal dan dokumentasi pelatihan insiden secara berkala.\r\n2. Modul pelatihan: identifikasi insiden, pelaporan, respon awal.\r\n3. Evaluasi efektivitas pelatihan melalui uji coba, simulasi atau quiz.\r\n4. Laporan improvement dari feedback pelatihan dan hasil simulasi sosial engineering.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(306, 4, 'GU 1.7', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi Anda menetapkan dan menerapkan prosedur back-up untuk semua data kritikal dan uji coba pengembalian data (restore) termasuk memastikan data integrity yang direview secara berkala?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Prosedur backup dan restore yang terdokumentasi dan ditetapkan.\r\n2. Log backup otomatis untuk semua data kritikal.\r\n3. Log uji restore berkala (misal triwulanan) dan bukti integritas data.\r\n4. Hasil audit dan tindakan korektif dari uji backup/restore yang gagal.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(307, 4, 'GU 1.8', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda menetapkan dan menerapkan proses pencatatan peristiwa keamanan (security event) dan insiden siber, termasuk penanganan dan penyelesaiannya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Sistem terotomatisasi untuk pencatatan security event dan insiden (SIEM/log server).\r\n2. Prosedur dokumentasi dan pelaporan insiden.\r\n3. Evaluasi triwulanan terhadap insiden yang terjadi.\r\n4. Bukti pemanfaatan data insiden untuk perbaikan kontrol keamanan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(308, 4, 'GU 1.9', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi Anda telah menetapkan dan menerapkan prosedur penyelidikan insiden yang meliputi identifikasi sistem, jaringan dan informasi yang terkena gangguan secara baku, sistematik, dan terstruktur?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Dokumen prosedur penyelidikan insiden (forensik digital, chain of custody).\r\n2. Checklist dan template penyelidikan insiden.\r\n3. Bukti implementasi prosedur dalam insiden nyata.\r\n4. Laporan evaluasi efektivitas investigasi dan tindak lanjutnya.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(309, 4, 'GU 1.10', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda menetapkan dan menerapkan kebijakan dan prosedur pengelolaan keberlangsungan layanan (Business Continuity Management)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Dokumen BCM yang ditandatangani pimpinan.\r\n2. Integrasi BCM dengan strategi dan manajemen risiko Organisasi.\r\n3. Audit tahunan terhadap implementasi BCM.\r\n4. Laporan evaluasi dan rencana perbaikannya.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(310, 4, 'GU 1.11', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda memiliki Business Impact Analysis (BIA) yang mencakup penentuan Recovery Time Objective (RTO) dan Recovery Point Objective (RPO) yang ditinjau ulang validitasnya secara berkala?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen BIA lengkap dengan matriks RTO dan RPO.\r\n2. Log peninjauan ulang validitas RTO/RPO tahunan.\r\n3. Bukti penggunaan BIA sebagai dasar dalam menyusun BCP dan strategi pemulihan.\r\n4. Dokumentasi evaluasi efektivitas terhadap penyesuaian BIA.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(311, 4, 'GU 1.12', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda menetapkan dan menerapkan rencana keberlangsungan layanan (Business Continuity Plan) untuk berbagai skenario yang relevan dengan konteks dan lingkup operasional?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1.Dokumen BCP mencakup skenario insiden TI, bencana alam, pandemi, dll.\r\n2. Simulasi tahunan dan laporan hasilnya.\r\n3. Laporan audit dan update berkala terhadap BCP berdasarkan hasil simulasi atau insiden nyata.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(312, 4, 'GU 1.13', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi Anda memiliki fasilitas cadangan (kantor alternatif dan/atau DRC) dengan sumber daya (daya listrik, jaringan internet, infrastruktur pendukung, infrastruktur komputasi dan jaringan cadangan) redundan untuk digunakan apabila terjadi gangguan karena insiden siber terhadap fasilitas kantor utama dan pusat data (DC)', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Dokumen perencanaan dan konfigurasi DRC/kantor alternatif.\r\n2. Bukti pengujian failover dari DC ke DRC (disaster recovery drill).\r\n3. Log pemeliharaan fasilitas cadangan (genset, UPS, internet, dll).\r\n4. Evaluasi dan perbaikan pasca uji/simulasi.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(313, 4, 'GU 1.14', 'Menyusun perencanaan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi Anda telah memastikan penerapan strategi pengembalian layanan (hot backup atau cold backup) dengan sumber daya redundan sesuai dengan standar pemenuhan layanan (RTO dan RPO yang sudah ditetapkan)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen strategi cold/hot backup.\r\n2. Hasil simulasi pengaktifan backup dan waktu pemulihan dibandingkan dengan target RTO/RPO.\r\n3. Audit terhadap kesiapan backup system dan efektivitasnya.\r\n4. Tindakan korektif berdasarkan hasil gap antara RTO/RPO aktual dengan target.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(314, 4, 'GU 2.15', 'Menganalisis dan melaporkan Insiden Siber', 'Apakah Organisasi anda menetapkan dan menerapkan metode untuk mengetahui potensi terjadinya suatu insiden siber (yang bersumber dari hasil audit internal, laporan karyawan, atau laporan stakeholder)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Prosedur tertulis dan formal mengenai penerimaan dan pengelolaan informasi potensi insiden siber dari berbagai sumber: audit internal, laporan karyawan (whistleblowing system), dan laporan stakeholder.\r\n2. Sistem pelaporan internal yang aktif (form/email hotline/portal).\r\n3. Log pelaporan dan tindak lanjut terhadap laporan karyawan/stakeholder (termasuk anonim).\r\n4. Evaluasi berkala efektivitas sistem pelaporan dan umpan baliknya.\r\n5. Bukti penyesuaian kebijakan atau perbaikan kontrol dari hasil laporan tersebut.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(315, 4, 'GU 2.16', 'Menganalisis dan melaporkan Insiden Siber', 'Apakah tersedia metode baku untuk mengidentifikasi dan menindaklanjuti kondisi yang membahayakan keamanan informasi dan menetapkannya sebagai insiden siber sesuai prosedur yang diberlakukan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen prosedur standar (SOP) klasifikasi dan eskalasi insiden siber.\r\n2. Template atau form identifikasi insiden yang dipakai secara konsisten.\r\n3. Log kasus nyata di mana prosedur digunakan untuk menetapkan peristiwa menjadi insiden resmi.\r\n4. Evaluasi rutin terhadap efektivitas metode penetapan insiden (misal melalui audit atau after action review).\r\n5. Perubahan/penyesuaian SOP berdasarkan hasil review atau insiden aktual.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(316, 4, 'GU 2.17', 'Menganalisis dan melaporkan Insiden Siber', 'Apakah Organisasi Anda membuat skema penilaian insiden dan prioritas berdasarkan potensial dampak (aspek kerugian operasional, bisnis, reputasi, dan hukum)?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen risk scoring matrix atau skema klasifikasi insiden berdasarkan dampak terhadap:\r\n      - Operasional\r\n      - Keuangan/bisnis\r\n      - Reputasi\r\n      - Hukum dan regulasi\r\n2. Formulir atau sistem klasifikasi insiden yang digunakan dalam setiap pelaporan.\r\n3. Laporan insiden dengan penilaian dan prioritas insiden yang diterapkan berdasarkan skema tersebut.\r\n4. Review berkala atas skema untuk memastikan masih relevan dengan dinamika ancaman dan bisnis.\r\n5. Bukti penyesuaian prioritas dalam tanggap insiden berdasarkan hasil penilaian aktual.\r\n6. SOP dan form Insiden', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(317, 4, 'GU 2.18', 'Menganalisis dan melaporkan Insiden Siber', 'Apakah tim respon insiden siber di Organisasi Anda memiliki kemampuan untuk melakukan analisis dan forensik dengan dilengkapi perangkat tertentu? (misalnya packet snifer, analisis protokol, alat forensik digital)', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. Daftar perangkat/tools forensik dan analisis yang tersedia di Organisasi (misal: FTK, Autopsy, Wireshark, Volatility, Sysinternals).\r\n2. Bukti pelatihan personel dalam menggunakan perangkat tersebut (sertifikat atau workshop internal).\r\n3. Prosedur tertulis forensik digital, termasuk chain of custody dan dokumentasi bukti.\r\n4. Laporan investigasi insiden siber yang menunjukkan penggunaan tools forensik.\r\n5. Evaluasi efektivitas kegiatan forensik (misal dalam pelaporan tahunan atau review insiden), termasuk rencana peningkatan kapabilitas.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(318, 4, 'GU 3.19', 'Melaksanakan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda telah menetapkan dan menerapkan rencana penanganan dan pemulihan berbagai skenario insiden siber (playbook atau incident response plan), yang kemudian disimulasikan, direviu dan dievaluasi secara berkala?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Dokumen Incident Response Plan (IRP) atau playbook untuk berbagai skenario insiden (mis. malware, phishing, DDoS, data breach).\r\n2. Simulasi insiden siber dilakukan secara berkala (minimal tahunan), dengan catatan/laporan hasil simulasi.\r\n3. Bukti adanya review dan pembaruan IRP berdasarkan hasil simulasi dan/atau insiden aktual.\r\n4. Notulen dan tindak lanjut dari hasil evaluasi, termasuk rencana perbaikan.\r\n5. Tim tanggap insiden mengetahui peran dan prosedurnya melalui pelatihan rutin.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(319, 4, 'GU 3.20', 'Melaksanakan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi Anda menetapkan dan menerapkan pelaporan insiden siber serta meneruskannya ke pihak eksternal seperti penegak hukum, institusi pemerintah terkait, vendor, dan mitra ISAC?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen kebijakan/prosedur pelaporan insiden ke eksternal (mis. BSSN, Polri, vendor, CERT, ISAC, CSIRT eksternal dsb).\r\n2. Daftar kontak dan protokol pelaporan ke setiap pihak eksternal, termasuk mekanisme eskalasi.\r\n3. Bukti insiden nyata yang pernah dilaporkan (dapat berupa redacted report atau log komunikasi/email ke pihak eksternal).\r\n4. Evaluasi berkala efektivitas proses pelaporan (mis. audit internal atau lessons learned).\r\n5. Bukti pelatihan staf mengenai tata cara pelaporan eksternal.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(320, 4, 'GU 3.21', 'Melaksanakan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda telah menetapkan dan menerapkan rencana pemulihan berbagai skenario bencana (disaster recovery plan), yang kemudian disimulasikan, direviu, dievaluasi secara berkala untuk menerapkan langkah perbaikan atau pembenahan yang diperlukan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen Disaster Recovery Plan (DRP) lengkap untuk berbagai skenario (mis. kerusakan pusat data, serangan ransomware, kegagalan jaringan).\r\n2. Jadwal dan bukti pelaksanaan simulasi DRP secara berkala (setidaknya tahunan).\r\n3. Laporan hasil simulasi yang mencakup RTO, RPO, pencapaian, dan kendala.\r\n4. Dokumen review dan update DRP secara berkala berdasarkan hasil simulasi atau perubahan sistem.\r\n5. Bukti bahwa hasil evaluasi dijadikan dasar untuk melakukan pembenahan atau investasi tambahan (misal upgrading DRC, backup system)', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(321, 4, 'GU 3.22', 'Melaksanakan penanggulangan dan pemulihan Insiden Siber', 'Apakah Organisasi anda telah menetapkan dan menerapkan protokol eskalasi dan koordinasi antara tim respon insiden dengan tim manajemen krisis apabila insiden siber berkembang menjadi bencana?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, '1. Dokumen protokol eskalasi antara tim tanggap insiden dan tim manajemen krisis (biasanya tertuang dalam DRP dan BCP).\r\n2. Diagram alur komunikasi dan otorisasi eskalasi ke level manajemen puncak.\r\n3. Bukti nyata eskalasi pernah dilakukan atau disimulasikan, termasuk laporan koordinasi dan keputusan yang diambil.\r\n4. Hasil evaluasi proses eskalasi dan peran koordinasi yang telah dilakukan.\r\n5. Bukti pelatihan gabungan antara tim teknis dan manajemen krisis.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(322, 4, 'GU 4.23', 'Meningkatkan keamanan setelah terjadinya Insiden Siber', 'Apakah Organisasi anda menerapkan proses dimana setelah penanganan insiden selesai, dilakukan dokumentasi pelaporan, direviu, dan disusun menjadi materi pembelajaran untuk pencegahan perulangan kejadian?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1. SOP atau prosedur baku terkait post-incident activity, termasuk dokumentasi, review, dan pembelajaran.\r\n2. Template pelaporan insiden (incident report) yang digunakan secara konsisten dan mencatat root cause, tindakan, dan hasil pemulihan.\r\n3. Bukti adanya review rapat pasca insiden (post-mortem meeting) dan notulen diskusinya.\r\n4. Materi pembelajaran internal dari insiden nyata yang digunakan untuk peningkatan kesadaran dan pelatihan internal.\r\n5. Bukti bahwa pembelajaran tersebut didistribusikan ke pihak terkait (teknis dan manajerial).', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(323, 4, 'GU 4.24', 'Meningkatkan keamanan setelah terjadinya Insiden Siber', 'Apakah Organisasi Anda menindaklanjuti pembelajaran pasca insiden (lesson learned) dengan perbaikan terkait kesiapan operasional, kecepatan tanggap dan waktu pemulihan, kemampuan SDM dalam menghadapi insiden, serta kelengkapan dan kesesuaian laporan penanganan insiden?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, '1. Laporan penanganan insiden, mencakup  lesson learned yang menyebutkan identifikasi gap dalam SDM, respon, recovery time, dan kualitas pelaporan.\r\n2. Catatan tindak lanjut atau rekomendasi dari hasil evaluasi insiden yang dijadikan dasar pembenahan SOP atau sistem.\r\n3. Bukti pengalokasian sumber daya atau pelatihan tambahan berdasarkan kelemahan yang ditemukan.\r\n4. Progres tracking atas tindak lanjut perbaikan dari setiap insiden signifikan.\r\n5. Bukti keterlibatan manajemen dalam proses review dan penyetujuan tindak lanjut.', 'Terdokumentasi di web csirt.pangkalpinangkota.go.id', '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(324, 4, 'GU 4.25', 'Meningkatkan keamanan setelah terjadinya Insiden Siber', 'Apakah Organisasi Anda menetapkan dan menerapkan prosedur untuk memperbaiki dan meningkatkan efektivitas kontrol dengan tujuan mengurangi frekuensi kejadian dan/atau dampak insiden yang meliputi: klasifikasi informasi, kontrol access, firewall, base line security?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, '1.SOP atau mekanisme baku untuk rekomendasi dan implementasi perbaikan kontrol pasca insiden.\r\n2. Laporan insiden yang mencantumkan rekomendasi perbaikan dan tindak lanjut teknis (misal: update firewall rule, access control revisi, revisi klasifikasi informasi).\r\n3. Catatan perubahan (change log) terhadap baseline keamanan atau sistem produksi pasca insiden.\r\n4. Bukti bahwa proses ini dikaji secara berkala untuk efektivitas (misal: audit pasca insiden, vulnerability re-assessment).\r\n5. Bukti penggunaan hasil evaluasi insiden sebagai input penguatan security policy dan awareness staff.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:56:00'),
(325, 4, 'GU 4.26', 'Meningkatkan keamanan setelah terjadinya Insiden Siber', 'Apakah Organisasi anda menetapkan dan menerapkan proses untuk melaporkan hasil reviu terhadap rekap laporan insiden siber kepada pimpinan puncak dan didistribusikan kepada para pemangku kepentingan serta digunakan dalam rangka mereviu kontrol yang ada untuk perbaikan respon penanganan insiden siber selanjutnya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Template laporan konsolidasi insiden (bulanan/triwulan) yang mencakup analisis tren dan rekomendasi.\r\n2. Bukti penyampaian laporan kepada pimpinan puncak (email disposisi, notulen rapat direksi, presentasi).\r\n3. Bukti distribusi laporan ke stakeholder terkait (mis. pemilik sistem, compliance, IT operations).\r\n4. Notulen forum evaluasi bersama yang membahas laporan ini dan arahan pimpinan untuk perbaikan lanjutan.\r\n5. Adanya integrasi laporan ini ke dalam evaluasi tahunan kebijakan keamanan atau pengembangan roadmap keamanan.', NULL, '2026-09-24 03:56:00', '2026-09-24 03:58:53'),
(326, 4, 'GU 4.27', 'Meningkatkan keamanan setelah terjadinya Insiden Siber', 'Apakah Organisasi Anda melakukan evaluasi tren keamanan berdasarkan rekaman insiden dan pelanggaran keamanan siber yang digunakan untuk mengidentifikasi faktor penyebab insiden, mengidentifikasi kelemahan implementasi teknologi dan kompetensi SDM, serta untuk mengidentifikasi berbagai tren terkait dampak bisnis, biaya penanganan insiden dan investasi sistem pencegahan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, '1. Laporan evaluasi tren keamanan berbasis data insiden dan pelanggaran (security trends report).\r\n2. Rekap dan Analisis tren mencakup kategori insiden, sumber penyebab, waktu pemulihan, biaya kerugian, dan efektivitas kontrol.\r\n3. Bukti laporan digunakan dalam strategi perencanaan mitigasi risiko, investasi sistem keamanan, atau peningkatan SDM.\r\n4. Bukti keterlibatan tim keamanan, manajemen risiko, dan manajemen SDM dalam proses evaluasi ini.\r\n5. Dokumentasi pembaruan kebijakan atau kontrol yang dilakukan sebagai hasil dari evaluasi tren.\r\n', NULL, '2026-09-24 03:56:00', '2026-09-24 03:58:47'),
(419, 5, 'SD 1.1', 'Kebijakan Pengamanan Informasi', 'Apakah di Organisasi terdapat unit kerja yang melaksanakan Urusan Persandian?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 5, NULL, 'Referensi: Eval Paminfo I.1', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(420, 5, 'SD 1.2', 'Kebijakan Pengamanan Informasi', 'Apakah unit kerja Persandian telah menjalankan tugas dan fungsinya sesuai dengan kewenangan yang diberikan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 5, NULL, 'Referensi: ID 1.2', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(421, 5, 'SD 1.3', 'Kebijakan Pengamanan Informasi', 'Apakah Unit Kerja Persandian telah menetapkan kebijakan dalam bentuk Peraturan Organisasi atau Peraturan Kepala Organisasi di bidang urusan Persandian untuk Pengamanan Informasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, NULL, 'Referensi: PR 3.20', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(422, 5, 'SD 1.4', 'Kebijakan Pengamanan Informasi', 'Apakah kebijakan terkait dengan Urusan Persandian dan Keamanan Informasi telah ditetakan dan disosialiasikan kepada seluruh pihak yang terkait?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 0, NULL, 'Referensi: ID 2.12', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(423, 5, 'SD 1.5', 'Kebijakan Pengamanan Informasi', 'Apakah Kebijakan terkait dengan Urusan Persandian dan Keamanan Informasi yang telah ditetapkan sudah dilakukan evaluasi kelaikannya secara berkala?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, NULL, 'Referensi: ID 2.16', '2026-09-24 07:47:03', '2026-09-24 07:47:03');
INSERT INTO `pertanyaan` (`id`, `topik_id`, `kode`, `kategori`, `pertanyaan`, `indeks_0`, `indeks_1`, `indeks_2`, `indeks_3`, `indeks_4`, `indeks_5`, `indeks_awal`, `panduan_indeks_5`, `keterangan_validasi_sumber`, `created_at`, `updated_at`) VALUES
(424, 5, 'SD 2.6', 'Pengelolaan Sumber Daya', 'Apakah dalam pengadaan perangkat keamanan TIK (alat untuk identifikasi dan deteksi insiden keamanan informasi, alat untuk memproteksi sistem elektronik, atau alat untuk membantu pemulihan insiden keamanan informasi) telah melalui proses analisis kebutuhan?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 5, NULL, 'Referensi: ID 1.2', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
