(450, 5, 'SD 3.32', 'Pengamanan Sistem Elektronik dan Informasi non Elektronik', 'Apakah Unit Kerja Persandian telah melaksanaan pengawasan/evaluasi pelaksanaan persandian di Organisasi atau Organisasi vertikalnya?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, NULL, 'Referensi: Eval Paminfo III.18', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(451, 5, 'SD 4.33', 'Layanan Keamanan Informasi', 'Apakah unit kerja urusan persandian telah menetapkan program kerja layanan keamanan informasi?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, NULL, 'Referensi: Eval Paminfo IV.1', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(452, 5, 'SD 4.34', 'Layanan Keamanan Informasi', 'Apakah Unit Kerja Urusan Persandian \r\nsudah melaksanakan evaluasi program kerja terhadap layanan keamanan informasi', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 2, NULL, 'Referensi: GU 3.21, PR.6.75, ID 2.11, ID 5.59', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(453, 5, 'SD 4.35', 'Layanan Keamanan Informasi', 'Apakah Pimpinan Organisasi telah memberikan dukungan dan komitmen terhadap program kerja sesuai dengan tugas dan wewenang pelaksanaan urusan persandian', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 3, NULL, 'Referensi: GU 1.9, PR.6.77, ID 1.1', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(454, 5, 'SD 5.36', 'Pola Hubungan Komunikasi Sandi', 'Apakah di Organisasi telah memiliki pola hubungan komunikasi sandi yang telah ditetapkan, paling sedikit memuat informasi sebagai berikut: \r\na. entitas pengguna layanan yang terhubung dalam JKS\r\nb. topologi atau bentuk atau model keterhubungan antar pengguna layanan\r\nc. sarana dan prasarana yang digunakan; dan\r\nd. tugas dan tanggungjawab pengelola dan pengguna layanan.', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, NULL, 'Referensi: Eval Paminfo V.1', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(455, 5, 'SD 5.37', 'Pola Hubungan Komunikasi Sandi', 'Dalam penetapan pola hubungan komunikasi sandi, Apakah sudah melalui identifikasi pola hubungan komunikasi sandi yang sekurang-kurangnya berisi informasi sebagai berikut:\r\na. alur informasi yang dikomunikasikan antar entitas dalam PHKS?\r\nb. teknologi informasi dan komunikasi yang digunakan.\r\nc. kondisi infrastruktur komunikasi; dan\r\nd. kebutuhan kompetensi personil yang akan mengawaki atau memanfaatkan JKS tersebut', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, NULL, 'Referensi: Eval Paminfo V.2', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(456, 5, 'SD 5.38', 'Pola Hubungan Komunikasi Sandi', 'Apakah hasil identifikasi pola hubungan komunikasi sandi telah dilakukan analisis, dimana hasilnya sekurang-kurangnya berisi informasi sebagai berikut:\r\na.	Penggunan layanan yang akan terhubung dalam JKS\r\nb.	Topologi atau bentuk atau model keterhubungan JKS antar pengguna\r\nc.	Perangkat keamanan teknologi informasi dan komunikasi, infrastuktur komunikasi, serta fasilitas lainnya yang dibutuhkan? dan\r\nd.	Penjabaran tugas dan tanggungjawab pengelola dan pengguna layanan.', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, NULL, 'Referensi: Eval Paminfo V.3', '2026-09-24 07:47:03', '2026-09-24 07:47:03'),
(457, 5, 'SD 5.39', 'Pola Hubungan Komunikasi Sandi', 'Apakah telah dilakukan pemantauan dan evaluasi terhadap penyelenggaraan pola hubungan komunikasi sandi dan membuat/menyampaikan laporan hasil pemantauan dan evaluasi secara berkala?', 'Belum ada penerapan kontrol', 'Penerapan masih dalam perencanaan atau masih bentuk awal', 'Sudah ada rancangan tapi belum lengkap /sesuai atau kontrol diterapkan tanpa dokumen/prosedur resmi', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, namun penerapan belum konsisten atau baru sebagian atau belum menyeluruh', 'Kontrol sudah diterapkan dan ditetapkan secara resmi, dan diterapkan secara konsisten dan menyeluruh', 'Dilakukan evaluasi pelaksanaan efektifitas kontrol dan upaya perbaikan', 1, NULL, 'Referensi: Eval Paminfo V.5', '2026-09-24 07:47:03', '2026-09-24 07:47:03');
